INSERT INTO public.topics (id, title, slug, usmle_step, "order", section, is_free_demo, mcq_count, case_count)
INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, difficulty, "order", type) VALUES
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 72-year-old woman presents with 3 days of vomiting and watery diarrhea, dizziness on standing, dry mucous membranes, and poor skin turgor. Blood pressure is 98/60 mmHg supine and 82/50 mmHg standing, heart rate 108/min. Labs show BUN 42 mg/dL, creatinine 2.1 mg/dL (baseline 0.9), sodium 138 mEq/L, and bicarbonate 22 mEq/L. Urinalysis shows specific gravity 1.030 with no protein, blood, or casts, and fractional excretion of sodium is 0.4%. What is the most appropriate next step in management?', '["Intravenous furosemide", "Intravenous isotonic saline", "Intravenous albumin infusion", "Emergent hemodialysis", "Kidney biopsy"]'::jsonb, 1, 'This is prerenal AKI from volume depletion: orthostatic hypotension, concentrated urine, BUN-to-creatinine ratio above 20, fractional excretion of sodium below 1%, and a bland sediment all indicate reduced renal perfusion with intact tubular function. Isotonic saline restores intravascular volume and renal perfusion, which typically reverses the creatinine rise. Furosemide would worsen volume depletion and further reduce perfusion. Albumin is reserved for specific indications such as hepatorenal syndrome or large-volume paracentesis, not simple hypovolemia. Hemodialysis is not indicated without refractory hyperkalemia, acidosis, uremia, or volume overload. Kidney biopsy has no role in a classic prerenal presentation.', 'Easy', 1, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 68-year-old man with heart failure with reduced ejection fraction (EF 25%) on lisinopril, carvedilol, and furosemide presents with worsening dyspnea, orthopnea, and lower-extremity edema. Blood pressure is 96/64 mmHg, jugular venous pressure is elevated, and an S3 gallop with bibasilar crackles is heard. Creatinine has risen from 1.0 to 1.9 mg/dL, BUN is 44 mg/dL, fractional excretion of sodium is 0.4%, and urinalysis is bland without proteinuria. What is the most likely cause of his acute kidney injury?', '["Cardiorenal syndrome with prerenal AKI", "Acute tubular necrosis", "Contrast-induced nephropathy", "Acute interstitial nephritis", "Postrenal obstruction"]'::jsonb, 0, 'Cardiorenal syndrome causes prerenal AKI through the combination of reduced cardiac output and elevated central venous pressure, which together lower renal perfusion pressure; the low fractional excretion of sodium and bland sediment confirm a prerenal pattern with preserved tubular function. Acute tubular necrosis would show muddy brown granular casts and a fractional excretion of sodium above 2%. There is no recent contrast exposure to explain contrast nephropathy. Acute interstitial nephritis typically presents with fever, rash, eosinophilia, and white blood cell casts. Postrenal obstruction would cause anuria or retention with hydronephrosis on imaging, which is absent here.', 'Medium', 2, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 58-year-old man with alcoholic cirrhosis and large-volume ascites on spironolactone and furosemide presents with oliguria. Creatinine has risen from 0.9 to 2.4 mg/dL over 5 days despite holding diuretics and receiving an albumin challenge. Sodium is 128 mEq/L, urine sodium is 8 mEq/L, urinalysis is bland with only a few hyaline casts, there is no proteinuria or hematuria, and renal ultrasound is normal. What is the most likely diagnosis?', '["Acute tubular necrosis", "Prerenal AKI from diuretics", "Hepatorenal syndrome", "Acute interstitial nephritis", "Bilateral renal artery stenosis"]'::jsonb, 2, 'Hepatorenal syndrome is a functional prerenal AKI in advanced cirrhosis caused by splanchnic vasodilation and intense renal vasoconstriction, with a bland sediment, very low urine sodium, and failure to improve after diuretic withdrawal and albumin volume expansion, which distinguishes it from simple prerenal azotemia. Acute tubular necrosis would show muddy brown casts and a fractional excretion of sodium above 2%. Prerenal AKI from diuretics should improve after holding diuretics and giving albumin. Acute interstitial nephritis presents with fever, rash, eosinophilia, and white blood cell casts. Renal artery stenosis causes refractory hypertension and a small kidney, not this picture.', 'Hard', 3, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 74-year-old woman with hypertension and osteoarthritis started ibuprofen for knee pain one week ago. She also takes lisinopril and hydrochlorothiazide. Creatinine has risen from 0.8 to 1.9 mg/dL, BUN is 34 mg/dL, potassium is 5.6 mEq/L, fractional excretion of sodium is 0.6%, and urinalysis shows a bland sediment. What is the most appropriate next step in management?', '["Add intravenous furosemide", "Start hemodialysis", "Obtain renal artery Doppler ultrasound", "Discontinue ibuprofen and lisinopril and give intravenous fluids", "Perform kidney biopsy"]'::jsonb, 3, 'This is hemodynamically mediated prerenal AKI from the triple combination of an NSAID, an ACE inhibitor, and a diuretic: NSAIDs block prostaglandin-mediated afferent arteriolar dilation while ACE inhibitors block angiotensin II-mediated efferent arteriolar constriction, so glomerular perfusion pressure collapses. The low fractional excretion of sodium and bland sediment confirm a prerenal pattern. The correct action is to stop the offending drugs and restore volume with intravenous fluids. Furosemide would worsen perfusion and hyperkalemia. Dialysis is not indicated for a creatinine of 1.9 without refractory complications. Doppler and biopsy are unnecessary when the drug-induced mechanism is clear.', 'Medium', 4, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 66-year-old man is on postoperative day 2 after abdominal aortic aneurysm repair complicated by intraoperative hypotension with systolic blood pressure in the 70s for 45 minutes. He is now oliguric. Creatinine has risen from 1.0 to 2.8 mg/dL, BUN is 40 mg/dL, fractional excretion of sodium is 2.8%, and urinalysis shows muddy brown granular casts without red blood cell casts or significant proteinuria. What is the most likely diagnosis?', '["Prerenal AKI", "Acute interstitial nephritis", "Contrast nephropathy", "Postrenal obstruction", "Ischemic acute tubular necrosis"]'::jsonb, 4, 'Prolonged hypotension caused ischemic injury to the renal tubules, producing acute tubular necrosis. The muddy brown granular casts are the classic urinalysis finding of ATN, and the fractional excretion of sodium above 2% reflects loss of tubular sodium reabsorption, distinguishing it from prerenal AKI, where the fractional excretion of sodium is below 1% and the sediment is bland. Acute interstitial nephritis would show fever, rash, eosinophilia, and white blood cell casts. Contrast nephropathy requires recent contrast exposure and typically peaks at 3 to 5 days. Postrenal obstruction would present with retention or anuria and hydronephrosis rather than muddy brown casts.', 'Medium', 5, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 59-year-old man has been treated with gentamicin for 10 days for infective endocarditis. Creatinine has risen from 1.0 to 2.5 mg/dL. He is nonoliguric, has no fever or rash, fractional excretion of sodium is 3.1%, and urinalysis shows muddy brown granular casts. What is the most likely cause of his acute kidney injury?', '["Aminoglycoside-induced acute tubular necrosis", "Acute interstitial nephritis", "Prerenal AKI", "Contrast nephropathy", "Atheroembolic disease"]'::jsonb, 0, 'Aminoglycosides accumulate in proximal tubular cells and cause nephrotoxic acute tubular necrosis, typically after 5 to 10 days of therapy, presenting with a rising creatinine, a fractional excretion of sodium above 2%, and muddy brown granular casts, often without oliguria. Acute interstitial nephritis would show fever, rash, eosinophilia, and white blood cell casts, which are absent. Prerenal AKI has a fractional excretion of sodium below 1% and a bland sediment. Contrast nephropathy requires recent contrast exposure. Atheroembolic disease follows arterial procedures and causes livedo reticularis, blue toes, and eosinophilia.', 'Medium', 6, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 70-year-old man developed acute tubular necrosis after septic shock. On day 10, his urine output has increased from 300 mL/day to 2500 mL/day, creatinine is 3.2 mg/dL (down from a peak of 4.1), and potassium is 4.8 mEq/L. He is hemodynamically stable and euvolemic. What is the most appropriate next step in management?', '["Start hemodialysis for persistent azotemia", "Restrict fluids aggressively", "Monitor electrolytes and replace urinary losses during the diuretic phase", "Perform kidney biopsy", "Give high-dose intravenous corticosteroids"]'::jsonb, 2, 'He has entered the diuretic phase of acute tubular necrosis, in which tubular function gradually recovers and urine output rises while creatinine lags behind; the main risks now are hypokalemia, hypomagnesemia, hypophosphatemia, and volume depletion from large urinary losses. Management is supportive monitoring with replacement of urinary electrolyte and fluid losses. Hemodialysis is not indicated because he is not oliguric, hyperkalemic, acidotic, or volume overloaded. Aggressive fluid restriction would cause hypovolemia during this high-output phase. Biopsy is unnecessary since the diagnosis and course are classic, and corticosteroids have no role in ATN.', 'Hard', 7, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 64-year-old woman with diabetes mellitus and chronic kidney disease (eGFR 38 mL/min/1.73 m2) is scheduled for coronary angiography. Which of the following is the most effective measure to prevent contrast-associated acute kidney injury?', '["Intravenous furosemide before the procedure", "N-acetylcysteine alone", "Mannitol infusion", "Dopamine infusion", "Periprocedural isotonic saline hydration with minimal contrast volume"]'::jsonb, 4, 'Periprocedural isotonic saline hydration is the most effective proven prevention for contrast-associated AKI, expanding intravascular volume and diluting contrast within the tubules, combined with using the lowest feasible contrast volume. Furosemide worsens volume depletion and increases risk. N-acetylcysteine has inconsistent evidence and is not a substitute for hydration. Mannitol and dopamine have no proven benefit and may cause harm. Additional measures include holding NSAIDs and avoiding nephrotoxins around the procedure, but hydration with contrast minimization remains the cornerstone of prevention.', 'Medium', 8, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 78-year-old man with chronic kidney disease stage 3b, diabetes mellitus, and heart failure undergoes percutaneous coronary intervention. His creatinine rises from 1.6 to 2.4 mg/dL at 48 hours, peaks on day 3, and then gradually recovers over the following week. Which of the following is the strongest risk factor for his contrast-associated acute kidney injury?', '["Male sex", "Preexisting chronic kidney disease with diabetes", "Concurrent statin use", "Young age", "Low-osmolality contrast agent"]'::jsonb, 1, 'Preexisting chronic kidney disease is the strongest risk factor for contrast-associated AKI, and diabetes markedly amplifies that risk because diabetic kidneys have reduced renal reserve and microvascular disease; the typical course is a creatinine rise at 24 to 72 hours peaking at 3 to 5 days, as seen here. Male sex is not an independent major risk factor, and statins do not increase contrast nephropathy risk. Young age is protective rather than a risk factor. Low-osmolality and iso-osmolal contrast agents reduce risk compared with high-osmolality agents, so they are protective, not harmful.', 'Medium', 9, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 71-year-old woman has a creatinine rise from 1.2 to 2.0 mg/dL 72 hours after a contrast-enhanced CT scan. She is nonoliguric, has no rash or eosinophilia, and urinalysis shows a bland sediment. What is the best next step in management?', '["Emergent hemodialysis", "Intravenous methylprednisolone", "Renal biopsy", "Supportive care with hydration and avoidance of nephrotoxins", "Intravenous furosemide"]'::jsonb, 3, 'This is classic contrast-associated AKI, which typically peaks 3 to 5 days after contrast exposure and then recovers with supportive care; management consists of intravenous hydration, holding NSAIDs and other nephrotoxins, and monitoring creatinine and electrolytes. Hemodialysis is not indicated without refractory hyperkalemia, acidosis, uremia, or volume overload. Corticosteroids treat allergic or interstitial disease, not contrast nephropathy, and there is no rash or eosinophilia to suggest an allergic mechanism. Renal biopsy is unnecessary for a clear temporal association with contrast. Furosemide would worsen volume depletion and does not prevent or treat contrast injury.', 'Medium', 10, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 24-year-old man is found down after lying immobile for 12 hours following an alcohol binge. He has severe muscle pain and dark tea-colored urine. Creatine kinase is 28,000 U/L, creatinine is 2.6 mg/dL, potassium is 6.1 mEq/L, calcium is 7.2 mg/dL, and phosphate is 6.0 mg/dL. Urinalysis dipstick is strongly positive for blood, but microscopy shows only a few red blood cells. What is the most likely diagnosis?', '["Rhabdomyolysis-induced acute kidney injury", "Acute glomerulonephritis", "Acute interstitial nephritis", "Contrast nephropathy", "Postrenal obstruction"]'::jsonb, 0, 'Prolonged immobility and muscle compression caused rhabdomyolysis, releasing myoglobin that is toxic to renal tubules and causes pigment-induced AKI. The dipstick-positive blood with few red blood cells on microscopy is the classic clue, since the dipstick detects myoglobin as well as hemoglobin. The markedly elevated creatine kinase, hyperkalemia, hypocalcemia, and hyperphosphatemia are the expected metabolic complications of muscle breakdown. Acute glomerulonephritis would show red blood cell casts and dysmorphic red cells. Acute interstitial nephritis presents with fever, rash, and eosinophilia. There is no contrast exposure or obstruction to explain the findings.', 'Easy', 11, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 30-year-old man with a crush injury to both legs has a creatine kinase of 45,000 U/L, creatinine of 2.2 mg/dL, potassium of 5.8 mEq/L, and urine output of 20 mL/hr. What is the most appropriate initial management?', '["Intravenous furosemide to force diuresis", "Restrict intravenous fluids", "Aggressive isotonic intravenous fluids targeting urine output of 200-300 mL/hr", "Emergent hemodialysis", "Intravenous sodium bicarbonate only"]'::jsonb, 2, 'Aggressive isotonic intravenous fluid resuscitation is the cornerstone of rhabdomyolysis management: it restores renal perfusion, dilutes myoglobin in the tubules, and maintains a high urine output of 200 to 300 mL/hr to prevent pigment cast formation and tubular obstruction. Furosemide does not improve outcomes and can worsen volume depletion. Restricting fluids would allow myoglobin to precipitate in the tubules and worsen kidney injury. Hemodialysis is reserved for refractory hyperkalemia, acidosis, or volume overload, none of which is present yet. Sodium bicarbonate alone is not a substitute for volume expansion.', 'Hard', 12, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 45-year-old man with rhabdomyolysis has a creatine kinase of 60,000 U/L, potassium of 6.4 mEq/L, calcium of 7.0 mg/dL, phosphate of 7.2 mg/dL, and pH of 7.28. ECG shows peaked T waves and a widened QRS complex. What is the most appropriate immediate treatment?', '["Intravenous calcium gluconate alone", "Oral sodium polystyrene sulfonate only", "Intravenous furosemide", "Restrict intravenous fluids", "Intravenous calcium gluconate, insulin with dextrose, and nebulized albuterol"]'::jsonb, 4, 'Severe hyperkalemia with ECG changes is a medical emergency requiring immediate membrane stabilization with intravenous calcium gluconate, followed by shifting potassium intracellularly with insulin plus dextrose and nebulized albuterol, while definitive potassium removal is arranged. Calcium alone stabilizes the myocardium but does not lower potassium, so it must be combined with shifting agents. Oral binders act too slowly for a life-threatening potassium of 6.4 with ECG changes. Furosemide is ineffective in oliguric AKI and does not acutely lower potassium. Restricting fluids would worsen the underlying rhabdomyolysis and kidney injury.', 'Hard', 13, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 52-year-old woman started omeprazole 3 weeks ago and now presents with fever, a maculopapular rash, peripheral eosinophilia, and a creatinine rise from 0.9 to 2.3 mg/dL. Urinalysis shows white blood cells, white blood cell casts, and eosinophiluria, without red blood cell casts. What is the most likely diagnosis?', '["Acute tubular necrosis", "Acute interstitial nephritis", "Acute glomerulonephritis", "Prerenal AKI", "Pyelonephritis"]'::jsonb, 1, 'Drug-induced acute interstitial nephritis is a hypersensitivity reaction to medications such as proton pump inhibitors, penicillins, and NSAIDs, classically presenting with fever, rash, eosinophilia, sterile pyuria, white blood cell casts, and eosinophiluria, typically 1 to 3 weeks after drug initiation. Acute tubular necrosis would show muddy brown granular casts and a fractional excretion of sodium above 2%. Acute glomerulonephritis presents with hematuria, red blood cell casts, and proteinuria. Prerenal AKI has a bland sediment and low fractional excretion of sodium. Pyelonephritis causes flank pain, fever, and bacteriuria with positive cultures, not eosinophiluria.', 'Medium', 14, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 40-year-old man has been receiving methicillin for 2 weeks for Staphylococcus aureus bacteremia. He now has fever, a maculopapular rash, eosinophilia, and a creatinine rise from 0.8 to 2.4 mg/dL. Urinalysis shows sterile pyuria and white blood cell casts. What is the most appropriate next step in management?', '["Continue methicillin and add intravenous fluids", "Start hemodialysis", "Perform kidney biopsy immediately", "Discontinue methicillin and consider corticosteroids if no improvement", "Give intravenous furosemide"]'::jsonb, 3, 'This is methicillin-induced acute interstitial nephritis, a classic hypersensitivity reaction, and the essential first step is to withdraw the offending drug, which often leads to recovery; corticosteroids are considered if kidney function does not improve after drug withdrawal, since early steroids may hasten recovery. Continuing methicillin would perpetuate the immune-mediated tubular injury. Hemodialysis is not indicated without refractory hyperkalemia, acidosis, uremia, or volume overload. Kidney biopsy can confirm the diagnosis but is not required before stopping the drug when the presentation is classic. Furosemide has no role and would worsen volume depletion.', 'Medium', 15, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 63-year-old man started an NSAID 10 days ago for back pain and now has a creatinine of 2.0 mg/dL (baseline 1.0), low-grade fever, and urinalysis showing white blood cells and eosinophils with a fractional excretion of sodium of 1.8% and no muddy brown casts. What is the most likely diagnosis?', '["Acute interstitial nephritis", "Acute tubular necrosis", "Prerenal AKI", "Postrenal obstruction", "Atheroembolic disease"]'::jsonb, 0, 'NSAID-induced acute interstitial nephritis presents about 1 to 2 weeks after drug initiation with fever, sterile pyuria, eosinophiluria, and a fractional excretion of sodium that is often intermediate, without the muddy brown casts of acute tubular necrosis. Acute tubular necrosis would show muddy brown granular casts and a fractional excretion of sodium above 2% following a hypotensive or nephrotoxic insult. Prerenal AKI has a fractional excretion of sodium below 1% and a bland sediment. Postrenal obstruction causes retention or anuria with hydronephrosis. Atheroembolic disease follows arterial procedures and causes livedo reticularis and blue toes.', 'Medium', 16, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 78-year-old man with benign prostatic hyperplasia presents with acute urinary retention, suprapubic pain, and a palpable bladder. Creatinine has risen from 1.0 to 3.0 mg/dL, BUN is 48 mg/dL, potassium is 5.5 mEq/L, and ultrasound shows bilateral hydronephrosis with a markedly distended bladder. What is the most appropriate next step in management?', '["Intravenous fluids only", "Hemodialysis", "Urinary catheterization with a Foley catheter", "Kidney biopsy", "Intravenous antibiotics"]'::jsonb, 2, 'This is postrenal AKI from bladder outlet obstruction due to benign prostatic hyperplasia, and the definitive treatment is prompt relief of the obstruction with a Foley catheter, which usually leads to rapid recovery of kidney function. Intravenous fluids alone do not relieve the obstruction and will worsen bladder distension. Hemodialysis is not indicated when the cause is reversible obstruction and there are no refractory complications. Kidney biopsy has no role in obstructive uropathy. Antibiotics are only indicated if there is a urinary tract infection, which is not described here.', 'Easy', 17, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 55-year-old woman with a history of nephrolithiasis presents with bilateral flank pain and anuria for 12 hours. Creatinine has risen from 1.0 to 4.2 mg/dL, potassium is 6.0 mEq/L, and ultrasound shows bilateral hydronephrosis without clearly visualized stones. What is the most appropriate next step in management?', '["Intravenous furosemide", "Hemodialysis", "Intravenous fluids and observation", "Kidney biopsy", "Urgent urology consultation for decompression with ureteral stent or nephrostomy"]'::jsonb, 4, 'Bilateral hydronephrosis with anuria indicates bilateral urinary obstruction, most likely from stones, and requires urgent decompression with a ureteral stent or percutaneous nephrostomy to preserve kidney function; delay risks irreversible renal damage. Furosemide cannot overcome a mechanical obstruction and will not restore urine flow. Hemodialysis treats the metabolic consequences but does not relieve the obstruction. Fluids and observation are inappropriate for anuric obstruction with hyperkalemia. Kidney biopsy has no role in obstructive uropathy and would be dangerous in this setting.', 'Medium', 18, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 70-year-old man had a Foley catheter placed for urinary retention from prostatic obstruction. Over the past 6 hours he has produced 600 mL of urine per hour. Sodium is 132 mEq/L, potassium is 3.2 mEq/L, and creatinine is falling. What is the most appropriate management?', '["Restrict all intravenous fluids", "Replace urine output with intravenous fluids and monitor electrolytes", "Give intravenous furosemide", "Remove the Foley catheter", "Start hemodialysis"]'::jsonb, 1, 'He has post-obstructive diuresis, a physiologic diuresis after relief of prolonged obstruction, which can cause rapid volume depletion, hypokalemia, hypomagnesemia, and hypophosphatemia if urinary losses are not replaced. Management is careful replacement of a portion of the urine output with intravenous fluids, with close monitoring of electrolytes and volume status. Restricting fluids would cause hypovolemia and prerenal AKI. Furosemide would worsen the electrolyte losses and volume depletion. Removing the catheter would re-obstruct him. Hemodialysis is not indicated since kidney function is improving and there are no refractory complications.', 'Medium', 19, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 72-year-old man presents 2 weeks after coronary angiography with livedo reticularis on his legs, blue toes with palpable pulses, and a creatinine rise from 1.1 to 2.6 mg/dL. Labs show peripheral eosinophilia, urinalysis has a few red blood cells without casts, and fundoscopy shows Hollenhorst plaques. What is the most likely diagnosis?', '["Contrast nephropathy", "Acute interstitial nephritis", "Cryoglobulinemia", "Cholesterol crystal (atheroembolic) disease", "Polyarteritis nodosa"]'::jsonb, 3, 'Cholesterol crystal embolization occurs when an arterial procedure dislodges cholesterol crystals from atherosclerotic plaque, showering emboli to the kidneys, skin, and eyes. The classic triad is livedo reticularis with blue toes despite palpable pulses, eosinophilia, and a subacute creatinine rise 1 to 2 weeks after the procedure, with Hollenhorst plaques in the retina confirming systemic embolization. Contrast nephropathy peaks at 3 to 5 days and lacks skin findings. Acute interstitial nephritis causes fever, rash, and white blood cell casts. Cryoglobulinemia causes palpable purpura and glomerulonephritis. Polyarteritis nodosa causes systemic vasculitis with aneurysms, not this picture.', 'Hard', 20, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 70-year-old man developed cholesterol emboli after coronary angiography, with acute kidney injury, livedo reticularis, blue toes, and peripheral eosinophilia. Which management approach is most appropriate?', '["Supportive care and avoidance of anticoagulation", "High-dose intravenous heparin", "Emergent hemodialysis", "Intravenous methylprednisolone pulses", "Renal artery stenting"]'::jsonb, 0, 'Management of cholesterol crystal embolization is supportive, including blood pressure control, statin therapy, and avoidance of anticoagulation and further arterial procedures, because anticoagulants can destabilize additional plaque and worsen embolization. Hemodialysis is only indicated for refractory uremic complications, not for the disease itself. High-dose heparin is specifically harmful in this condition and should be avoided. Corticosteroids have no proven benefit and are not standard therapy. Renal artery stenting treats atherosclerotic renal artery stenosis, not cholesterol embolization, and would risk further plaque disruption.', 'Hard', 21, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 60-year-old man with acute kidney injury has a potassium of 7.0 mEq/L with peaked T waves and a widened QRS complex on ECG. He has already received intravenous calcium gluconate, insulin with dextrose, nebulized albuterol, and sodium bicarbonate, but the potassium remains 6.8 mEq/L with persistent ECG changes. What is the most appropriate next step?', '["Oral sodium zirconium cyclosilicate only", "Intravenous furosemide", "Emergent hemodialysis", "Sodium bicarbonate infusion alone", "Observation"]'::jsonb, 2, 'Refractory hyperkalemia with ECG changes that does not respond to medical therapy is a classic indication for urgent dialysis, remembered by the AEIOU mnemonic: acidosis, electrolytes, intoxications, overload, and uremia. Hemodialysis rapidly and reliably removes potassium when the kidneys cannot. Oral potassium binders act too slowly for a life-threatening potassium with ECG changes. Furosemide is ineffective in oliguric AKI and cannot remove potassium fast enough. Additional bicarbonate alone will not correct a potassium of 6.8. Observation is dangerous because hyperkalemia can precipitate fatal arrhythmia at any moment.', 'Medium', 22, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 58-year-old woman with acute kidney injury has a BUN of 120 mg/dL and creatinine of 6.5 mg/dL. She reports chest pain that worsens when lying flat and improves when sitting forward. Examination reveals a pericardial friction rub, and ECG shows diffuse ST-segment elevation with a small pericardial effusion on echocardiography. What is the most appropriate next step in management?', '["NSAIDs and colchicine", "Pericardiocentesis", "Intravenous heparin", "High-dose corticosteroids", "Urgent hemodialysis"]'::jsonb, 4, 'Uremic pericarditis is a complication of severe uremia and is an indication for urgent dialysis, since removing uremic toxins resolves the pericardial inflammation. NSAIDs and colchicine treat viral or idiopathic pericarditis but are ineffective and potentially harmful in uremic pericarditis, and NSAIDs would further worsen kidney function. Pericardiocentesis is reserved for cardiac tamponade, which is not present given only a small effusion. Heparin is contraindicated because uremic pericarditis carries a high risk of hemorrhagic pericardial effusion. Corticosteroids do not treat the underlying uremia.', 'Hard', 23, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 65-year-old man with acute kidney injury is anuric with severe dyspnea and pulmonary edema that has not improved despite high-dose intravenous furosemide. Arterial blood gas shows pH 7.18 and bicarbonate 12 mEq/L, and potassium is 6.0 mEq/L. What is the most appropriate next step in management?', '["More intravenous furosemide", "Urgent hemodialysis", "Intravenous sodium bicarbonate alone", "Noninvasive ventilation only", "Fluid challenge"]'::jsonb, 1, 'Refractory volume overload and severe metabolic acidosis in anuric AKI are both indications for urgent dialysis under the AEIOU mnemonic. Hemodialysis simultaneously removes excess volume, corrects acidosis, and lowers potassium, which no single medical therapy can achieve in an anuric patient. Additional furosemide is futile because the kidneys cannot excrete the fluid. Sodium bicarbonate alone cannot correct the volume overload or the potassium. Noninvasive ventilation supports breathing but does not remove volume or correct acidosis. A fluid challenge would worsen the pulmonary edema.', 'Medium', 24, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 75-year-old woman with acute kidney injury has a fractional excretion of sodium of 0.5%. She is not taking diuretics, and urinalysis shows a bland sediment with no casts or proteinuria. Which of the following is this finding most consistent with?', '["Acute tubular necrosis", "Acute interstitial nephritis", "Acute glomerulonephritis", "Prerenal AKI", "Postrenal obstruction"]'::jsonb, 3, 'A fractional excretion of sodium below 1% indicates that the tubules are avidly reabsorbing sodium, which occurs when renal perfusion is reduced but tubular function is intact, the hallmark of prerenal AKI. Acute tubular necrosis damages the tubules so they cannot reabsorb sodium, producing a fractional excretion above 2% with muddy brown casts. Acute interstitial nephritis typically has a fractional excretion of sodium above 1% with white blood cell casts and eosinophiluria. Acute glomerulonephritis presents with hematuria, red blood cell casts, and proteinuria. Postrenal obstruction can have a variable fractional excretion and would show hydronephrosis.', 'Medium', 25, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 60-year-old man with acute kidney injury has a urinalysis showing muddy brown granular casts and a fractional excretion of sodium of 2.5%. He had a prolonged hypotensive episode during surgery 2 days ago. What is the most likely diagnosis?', '["Acute tubular necrosis", "Prerenal AKI", "Acute interstitial nephritis", "Postrenal obstruction", "Minimal change disease"]'::jsonb, 0, 'Muddy brown granular casts are the classic urinalysis finding of acute tubular necrosis, representing sloughed tubular epithelial cells, and a fractional excretion of sodium above 2% confirms that damaged tubules cannot reabsorb sodium. The preceding hypotensive episode provides the ischemic insult. Prerenal AKI would have a fractional excretion of sodium below 1% and a bland sediment. Acute interstitial nephritis shows white blood cell casts and eosinophiluria. Postrenal obstruction presents with retention or anuria and hydronephrosis. Minimal change disease causes heavy proteinuria with fatty casts, not muddy brown casts.', 'Easy', 26, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'An 80-year-old man with acute kidney injury is anuric and has a history of prostate cancer with known pelvic metastases. Creatinine is rising rapidly. Which test is best to evaluate for urinary obstruction as the cause of his AKI?', '["Kidney biopsy", "CT abdomen with contrast", "Renal ultrasound", "Fractional excretion of sodium", "Serum protein electrophoresis"]'::jsonb, 2, 'Renal ultrasound is the first-line test for suspected urinary obstruction because it is noninvasive, avoids contrast and radiation, and directly demonstrates hydronephrosis and bladder distension; it is the standard initial imaging study in AKI workup when obstruction is possible. Kidney biopsy is invasive and has no role in obstructive uropathy. CT with contrast risks worsening kidney injury and is not first-line. Fractional excretion of sodium helps distinguish prerenal from tubular causes but does not diagnose obstruction. Serum protein electrophoresis evaluates for multiple myeloma, which is not suggested by this presentation.', 'Medium', 27, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 68-year-old woman with acute kidney injury (creatinine clearance 20 mL/min) is being treated with vancomycin for methicillin-resistant Staphylococcus aureus bacteremia. Which of the following is the most appropriate approach to her vancomycin dosing?', '["Continue standard dosing", "Increase the dose", "Switch to oral vancomycin", "Stop vancomycin", "Reduce the dose or extend the dosing interval with trough monitoring"]'::jsonb, 4, 'Vancomycin is cleared almost entirely by the kidneys, so in AKI with a creatinine clearance of 20 mL/min the dose must be reduced or the interval extended, with trough levels monitored to maintain efficacy while avoiding accumulation and further nephrotoxicity and ototoxicity. Continuing standard dosing would cause drug accumulation and worsen kidney injury. Increasing the dose is dangerous in renal impairment. Oral vancomycin is not absorbed systemically and cannot treat bacteremia. Stopping vancomycin would leave MRSA bacteremia untreated, which is life-threatening.', 'Medium', 28, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 62-year-old man with acute kidney injury has a creatinine of 2.4 mg/dL (baseline 1.0). His medications include ibuprofen for chronic back pain and lisinopril for hypertension. Urinalysis shows a bland sediment with a fractional excretion of sodium of 0.7%. What is the most appropriate medication change?', '["Continue both medications", "Hold ibuprofen and lisinopril", "Add spironolactone", "Add intravenous contrast for imaging", "Start gentamicin"]'::jsonb, 1, 'This is hemodynamically mediated prerenal AKI: the NSAID blocks prostaglandin-mediated afferent arteriolar dilation while the ACE inhibitor blocks angiotensin II-mediated efferent arteriolar constriction, collapsing glomerular perfusion pressure, as confirmed by the low fractional excretion of sodium and bland sediment. Both drugs should be held and volume restored to allow kidney recovery. Continuing them would perpetuate the injury. Adding spironolactone would worsen hyperkalemia and reduce perfusion further. Intravenous contrast and gentamicin are additional nephrotoxins that would worsen the kidney injury and delay recovery.', 'Medium', 29, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 76-year-old man on furosemide develops acute kidney injury with a creatinine rise from 1.0 to 2.2 mg/dL. Fractional excretion of sodium is 1.5%, which is unreliable because diuretics increase urinary sodium excretion. Which test best helps distinguish prerenal AKI from acute tubular necrosis in this patient?', '["Kidney biopsy", "Serum osmolality", "Urine protein-to-creatinine ratio", "Fractional excretion of urea (FeUrea below 35% suggests prerenal AKI)", "ANCA testing"]'::jsonb, 3, 'Fractional excretion of urea remains reliable in patients on diuretics because urea reabsorption is less affected by loop diuretics than sodium reabsorption; a value below 35% suggests prerenal AKI with intact tubular function, while a value above 50% suggests acute tubular necrosis. Kidney biopsy is invasive and unnecessary for this distinction. Serum osmolality does not differentiate prerenal from tubular causes. The urine protein-to-creatinine ratio assesses proteinuria, not tubular function. ANCA testing evaluates for vasculitis, which is not suggested by this presentation.', 'Hard', 30, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 68-year-old man with type 2 diabetes mellitus and hypertension has an estimated glomerular filtration rate (eGFR) of 42 mL/min/1.73 m² and a urine albumin-to-creatinine ratio of 320 mg/g. He takes lisinopril 10 mg daily, his blood pressure is 138/82 mm Hg, and his hemoglobin A1c is 7.4%. Which of the following is the most appropriate next step to slow progression of his chronic kidney disease?', '["Add an SGLT2 inhibitor such as dapagliflozin", "Stop lisinopril and start amlodipine", "Start a high-protein diet", "Refer for hemodialysis now", "Restrict dietary potassium only"]'::jsonb, 0, 'SGLT2 inhibitors reduce intraglomerular pressure and slow the decline in kidney function in diabetic kidney disease with albuminuria, and their benefit is additive to ACE inhibitor therapy, making them the appropriate next step here. Stopping lisinopril would remove RAAS blockade that reduces proteinuria and slows progression. A high-protein diet increases intraglomerular pressure and accelerates kidney injury, whereas protein intake is usually moderated, not increased. Hemodialysis is not indicated at an eGFR of 42 without refractory uremic complications. Potassium restriction alone does not slow disease progression.', 'Medium', 31, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 58-year-old woman with hypertension and chronic kidney disease has an eGFR of 52 mL/min/1.73 m² and a urine albumin-to-creatinine ratio of 45 mg/g. Her blood pressure is 148/92 mm Hg on amlodipine 5 mg daily. She has no edema and her serum potassium is 4.3 mEq/L. Which of the following is the most appropriate next step in her management?', '["Add hydrochlorothiazide", "Add lisinopril and target blood pressure below 130/80 mm Hg", "Start planning for dialysis", "Restrict dietary protein to 0.3 g/kg/day", "Stop all antihypertensive medications"]'::jsonb, 1, 'An ACE inhibitor reduces albuminuria and slows chronic kidney disease progression, and blood pressure control below 130/80 mm Hg is the target in kidney disease with albuminuria, so adding lisinopril is the best next step. A thiazide diuretic alone does not provide the antiproteinuric benefit of RAAS blockade. Dialysis planning is premature at an eGFR of 52 without uremic complications. Restricting protein to 0.3 g/kg/day is excessively severe and risks malnutrition; moderate restriction around 0.8 g/kg/day is advised. Stopping antihypertensives would worsen hypertension and accelerate progression.', 'Medium', 32, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 72-year-old man with chronic kidney disease has an eGFR of 28 mL/min/1.73 m², down from 38 six months ago, with a urine albumin-to-creatinine ratio of 120 mg/g. He takes lisinopril and amlodipine, his blood pressure is 128/76 mm Hg, and he has no uremic symptoms. Which of the following is the most appropriate next step?', '["Continue primary care follow-up only", "Start hemodialysis now", "Refer to nephrology", "Stop the ACE inhibitor", "Begin peritoneal dialysis training"]'::jsonb, 2, 'Nephrology referral is recommended when eGFR falls below 30 mL/min/1.73 m² so that a specialist can review medications, manage complications, and begin planning for kidney replacement therapy before it becomes urgent. Primary care follow-up alone is insufficient at stage G4 disease. Hemodialysis is not yet indicated without uremic symptoms or refractory complications such as hyperkalemia or volume overload. The ACE inhibitor should generally be continued for its antiproteinuric and cardioprotective effects. Peritoneal dialysis training comes after referral and shared decision-making, not before specialist evaluation.', 'Easy', 33, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 64-year-old man on maintenance hemodialysis has a hemoglobin of 9.4 g/dL despite epoetin alfa therapy. His ferritin is 160 ng/mL and transferrin saturation is 16%. He has no evidence of bleeding, and his dialysis adequacy is good. Which of the following is the most appropriate next step in managing his anemia?', '["Increase the epoetin alfa dose", "Give a red blood cell transfusion", "Start oral ferrous sulfate", "Give intravenous iron sucrose", "Stop epoetin alfa"]'::jsonb, 3, 'A transferrin saturation of 16% indicates absolute iron deficiency despite a ferritin of 160 ng/mL, and iron deficiency blunts the response to erythropoiesis-stimulating agents, so intravenous iron is needed. In hemodialysis patients intravenous iron is preferred because oral iron is poorly absorbed and often ineffective. Increasing epoetin without iron wastes the drug and raises risk without correcting the deficiency. Transfusion is reserved for symptomatic severe anemia or acute bleeding. Stopping epoetin would worsen the anemia rather than treat its cause.', 'Medium', 34, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 70-year-old woman with stage 4 chronic kidney disease has a serum phosphate of 6.1 mg/dL, calcium of 8.6 mg/dL, parathyroid hormone of 410 pg/mL, and 25-hydroxyvitamin D of 14 ng/mL. She has bone pain and no history of fractures. Which of the following is the most appropriate next step in managing her mineral and bone disorder?', '["Give intravenous calcium gluconate", "Start cinacalcet", "Give high-dose vitamin D alone", "Perform parathyroidectomy now", "Dietary phosphate restriction and a phosphate binder"]'::jsonb, 4, 'Hyperphosphatemia with secondary hyperparathyroidism in stage 4 kidney disease is managed first with dietary phosphate restriction and a phosphate binder, with vitamin D repletion as needed, to lower phosphate and parathyroid hormone. Intravenous calcium gluconate is for symptomatic hypocalcemia, which she does not have. Cinacalcet is used mainly in dialysis patients with secondary hyperparathyroidism, not as first-line therapy in stage 4. High-dose vitamin D alone raises calcium and phosphate and can worsen hyperphosphatemia. Parathyroidectomy is reserved for severe refractory hyperparathyroidism.', 'Hard', 35, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 52-year-old man with chronic alcohol use is admitted with vomiting and weakness. His potassium is 2.9 mEq/L, magnesium is 1.0 mg/dL, calcium is 7.8 mg/dL, and phosphate is 1.9 mg/dL. His hypokalemia has not improved despite repeated potassium chloride infusions. Which of the following is the most appropriate next step?', '["Give intravenous magnesium sulfate", "Give intravenous calcium gluconate", "Increase the potassium chloride infusion rate", "Give oral phosphate repletion only", "Give intravenous sodium bicarbonate"]'::jsonb, 0, 'Magnesium deficiency impairs Na-K-ATPase activity and opens renal outer medullary potassium channels, increasing urinary potassium wasting, so hypokalemia remains refractory until magnesium is repleted; chronic alcohol use, vomiting, and malnutrition all cause magnesium loss. Intravenous magnesium sulfate corrects the underlying defect and allows potassium to normalize. Calcium gluconate treats symptomatic hypocalcemia but does nothing for potassium wasting. More potassium chloride alone fails while magnesium remains low. Phosphate repletion alone does not address the potassium loss. Bicarbonate worsens hypokalemia and hypocalcemia by shifting ions intracellularly.', 'Hard', 36, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 60-year-old man with end-stage renal disease has an eGFR of 7 mL/min/1.73 m² and presents with confusion, asterixis, a pericardial friction rub, and a serum potassium of 6.4 mEq/L that has not responded to medical therapy. His blood pressure is 150/90 mm Hg and he has mild peripheral edema. Which of the following is the most appropriate next step?', '["Give oral sodium bicarbonate", "Start urgent hemodialysis", "Give intravenous calcium gluconate only", "Give a high-dose loop diuretic", "Restrict dietary potassium"]'::jsonb, 1, 'Uremic encephalopathy with uremic pericarditis and refractory hyperkalemia are absolute indications for dialysis, and no medical therapy reverses uremic encephalopathy or pericarditis, so urgent hemodialysis is the definitive treatment. Oral sodium bicarbonate treats metabolic acidosis but does not clear uremic toxins or resolve encephalopathy. Calcium gluconate stabilizes the cardiac membrane transiently but does not remove potassium or uremic toxins. Loop diuretics fail in end-stage disease with minimal residual kidney function. Dietary potassium restriction acts far too slowly for encephalopathy and refractory hyperkalemia.', 'Medium', 37, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 45-year-old woman with end-stage renal disease lives two hours from the nearest dialysis center, works from home, and has strong family support. She has never had abdominal surgery and wants as much independence as possible. She has no living kidney donor. Which of the following is the most appropriate kidney replacement modality for her?', '["In-center hemodialysis three times weekly", "Kidney transplantation now", "Peritoneal dialysis", "Conservative management without dialysis", "Daily nocturnal in-center hemodialysis"]'::jsonb, 2, 'Peritoneal dialysis is home-based, preserves residual kidney function, and avoids thrice-weekly long-distance travel, making it ideal for a motivated patient with good support and no abdominal contraindications. In-center hemodialysis would burden her with long travel three times a week. Kidney transplantation is the best long-term option but requires evaluation and a donor, so it is not immediately available. Conservative management is for patients who decline dialysis or have limited life expectancy. Daily in-center hemodialysis still requires the same long travel.', 'Medium', 38, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 58-year-old man on maintenance hemodialysis through an arteriovenous fistula develops a fever of 38.9°C with rigors during dialysis. Examination shows erythema and tenderness over the fistula, and his blood pressure is 90/60 mm Hg. Which of the following is the most appropriate next step?', '["Start oral amoxicillin", "Remove the fistula immediately", "Give antipyretics and observe", "Obtain blood cultures and give intravenous vancomycin", "Switch to peritoneal dialysis"]'::jsonb, 3, 'Fever with rigors and inflammation over the fistula suggests an access-related bloodstream infection, most often Staphylococcus aureus, so blood cultures should be drawn before antibiotics and empiric intravenous vancomycin started to cover methicillin-resistant Staphylococcus aureus. Oral amoxicillin is inadequate for possible MRSA bacteremia and cannot achieve reliable blood levels in this setting. Immediate fistula removal is premature before cultures and source assessment. Observation risks progression to septic shock and metastatic infection. Switching dialysis modality does not treat the infection. Vancomycin is chosen empirically because methicillin-resistant Staphylococcus aureus is the most common cause of access-related bacteremia, and treatment continues for at least two weeks after the first negative blood culture.', 'Medium', 39, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 66-year-old man with end-stage renal disease missed his last two dialysis sessions and presents with muscle weakness. His serum potassium is 7.2 mEq/L, and his ECG shows peaked T waves with a widened QRS complex. His blood pressure is 100/60 mm Hg. Which of the following is the most appropriate immediate treatment?', '["Give intravenous insulin and glucose", "Give oral sodium polystyrene sulfonate", "Give nebulized albuterol", "Give intravenous furosemide", "Give intravenous calcium gluconate"]'::jsonb, 4, 'With ECG changes from severe hyperkalemia, intravenous calcium gluconate is given first to stabilize the cardiac membrane within minutes, even though it does not lower the potassium level. Insulin and glucose shift potassium intracellularly but take 15 to 30 minutes to act and do not stabilize the membrane. Oral binders act over hours and are unreliable in an emergency. Nebulized albuterol is only an adjunct shifting therapy, never the first treatment when ECG changes are present. Furosemide is ineffective in end-stage renal disease with minimal urine output.', 'Easy', 40, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 62-year-old woman with diabetic chronic kidney disease has an eGFR of 38 mL/min/1.73 m² and takes lisinopril 10 mg daily. Her serum potassium is 5.6 mEq/L, she has no symptoms, and her ECG is normal. Which of the following is the most appropriate next step?', '["Add patiromer, continue lisinopril, and restrict dietary potassium", "Stop lisinopril permanently", "Start hemodialysis", "Give intravenous calcium gluconate", "Give a high-dose loop diuretic"]'::jsonb, 0, 'Mild chronic hyperkalemia on a renin-angiotensin system inhibitor is best managed by continuing the kidney- and cardioprotective ACE inhibitor while lowering potassium with dietary restriction and a binder such as patiromer. Stopping lisinopril sacrifices renoprotection and is reserved for severe or refractory hyperkalemia. Dialysis is not indicated at an eGFR of 38 without uremic complications. Calcium gluconate is for ECG changes, which are absent here. Loop diuretics are unreliable for chronic potassium control in advancing kidney disease. Potassium binders such as patiromer exchange potassium for calcium in the gut and lower serum potassium over days without removing the kidney protection of the ACE inhibitor.', 'Medium', 41, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 70-year-old man with stage 4 chronic kidney disease has a serum potassium of 6.3 mEq/L and a normal ECG. He has no muscle weakness, and his next dialysis session is scheduled for tomorrow. Which of the following is the most appropriate immediate treatment?', '["Give oral sodium bicarbonate", "Give intravenous regular insulin with dextrose", "Give intravenous calcium gluconate", "Give oral sodium polystyrene sulfonate", "Observe until his dialysis session tomorrow"]'::jsonb, 1, 'Intravenous insulin with dextrose shifts potassium intracellularly within 15 to 30 minutes and is the fastest potassium-lowering therapy available while awaiting dialysis. Sodium bicarbonate is reserved for significant metabolic acidosis and acts more slowly on potassium. Calcium gluconate is indicated only when ECG changes are present, and this patient''s ECG is normal. Oral binders work over hours and are unreliable in the acute setting. Observation risks progression to a life-threatening arrhythmia with a potassium of 6.3 mEq/L. Dextrose is given with the insulin to prevent hypoglycemia, and the potassium-lowering effect lasts four to six hours, so repeat treatment or dialysis is still needed.', 'Medium', 42, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 78-year-old woman taking hydrochlorothiazide for hypertension presents with confusion and a serum sodium of 122 mEq/L. She has orthostatic hypotension, dry mucous membranes, poor oral intake, and an elevated blood urea nitrogen-to-creatinine ratio. Which of the following is the most appropriate next step?', '["Restrict fluid intake", "Give hypertonic saline", "Stop hydrochlorothiazide and give isotonic saline", "Give demeclocycline", "Give desmopressin"]'::jsonb, 2, 'Thiazide diuretic use combined with volume depletion causes hypovolemic hyponatremia, so stopping the diuretic and restoring volume with isotonic saline is the correct treatment. Fluid restriction is for euvolemic SIADH and would worsen hypovolemia in this patient. Hypertonic saline is reserved for severe symptomatic hyponatremia with neurologic symptoms such as seizures. Demeclocycline treats SIADH, not hypovolemia. Desmopressin retains free water and would worsen the hyponatremia. Volume status is the key distinction here: hypovolemic hyponatremia needs saline, whereas euvolemic hyponatremia from SIADH needs fluid restriction, so examining the patient carefully guides the correct treatment.', 'Easy', 43, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 64-year-old man with small cell lung cancer has a serum sodium of 118 mEq/L. He is clinically euvolemic, his serum osmolality is 250 mOsm/kg, urine osmolality is 520 mOsm/kg, and urine sodium is 68 mEq/L. He is alert with no seizures. Which of the following is the most appropriate initial treatment?', '["Give isotonic saline infusion", "Give a loop diuretic alone", "Give hypertonic saline", "Restrict fluid intake", "Give demeclocycline immediately"]'::jsonb, 3, 'Euvolemic hyponatremia with a concentrated urine and high urine sodium in a patient with malignancy is SIADH, and fluid restriction is first-line therapy for mild to moderate asymptomatic cases. Isotonic saline worsens hyponatremia in SIADH by adding free water that the kidney cannot excrete. Loop diuretics alone are not first-line treatment for SIADH. Hypertonic saline is reserved for severe neurologic symptoms such as seizures or coma. Demeclocycline is a second-line agent for refractory SIADH, not initial therapy. Treating the underlying malignancy is also important, since SIADH from small cell lung cancer often improves when the tumor responds to chemotherapy.', 'Medium', 44, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 58-year-old woman has chronic hyponatremia that developed over several weeks, with a serum sodium of 110 mEq/L and mild confusion but no seizures or coma. Which of the following is the maximum safe rate of sodium correction for this patient?', '["Correct by 4 mEq/L per day", "Correct by 15 mEq/L per day", "Correct by 20 mEq/L per day", "Correct to normal within 6 hours", "Correct by no more than 8 mEq/L in the first 24 hours"]'::jsonb, 4, 'Rapid correction of chronic hyponatremia risks osmotic demyelination syndrome, so correction should be limited to 8 to 10 mEq/L in 24 hours, with 8 mEq/L the safer limit in high-risk patients. Correcting only 4 mEq/L per day is unnecessarily slow and prolongs symptoms without added benefit. Correcting 15 or 20 mEq/L per day greatly increases the risk of demyelination and permanent neurologic injury. Normalizing the sodium within 6 hours is dangerous in chronic hyponatremia and should never be attempted. If overcorrection occurs, desmopressin and hypotonic fluids can be used to relower the sodium and reduce the risk of demyelination.', 'Hard', 45, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 72-year-old man with multiple myeloma presents with confusion, polyuria, and constipation. His serum calcium is 13.4 mg/dL and creatinine is 2.1 mg/dL. Which of the following is the most appropriate initial treatment?', '["Give aggressive intravenous isotonic saline", "Give intravenous furosemide first", "Restrict dietary calcium", "Give calcitonin alone", "Start hemodialysis"]'::jsonb, 0, 'Severe hypercalcemia with volume depletion is treated first with aggressive isotonic saline to restore intravascular volume and promote urinary calcium excretion, and this precedes all other therapies. Furosemide given before volume repletion worsens dehydration and is no longer first-line treatment. Dietary calcium restriction is too slow and ineffective in severe hypercalcemia. Calcitonin is an adjunct with only a transient effect, not initial monotherapy. Hemodialysis is reserved for refractory cases or severe renal failure. After volume repletion, a bisphosphonate such as zoledronic acid or calcitonin can be added to lower calcium further in severe or symptomatic cases.', 'Medium', 46, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 45-year-old woman is on postoperative day 1 after total thyroidectomy and reports perioral numbness and tingling in her hands. Examination shows positive Chvostek and Trousseau signs. Her serum calcium is 6.8 mg/dL and parathyroid hormone is low. Which of the following is the most appropriate treatment?', '["Give oral calcium carbonate", "Give intravenous calcium gluconate", "Give intravenous magnesium sulfate", "Give calcitriol alone", "Reassure and observe"]'::jsonb, 1, 'Symptomatic hypocalcemia after thyroidectomy with tetany signs requires intravenous calcium gluconate for rapid correction, as oral calcium acts too slowly when tetany is present. Oral calcium carbonate is appropriate for mild asymptomatic hypocalcemia but not for symptomatic disease. Magnesium is given only if deficient, but calcium is the immediate need here. Calcitriol helps with chronic management but acts too slowly in the acute setting. Observation risks laryngospasm, seizures, and cardiac arrhythmia. Calcitriol and oral calcium are added for longer-term management, and the parathyroid glands usually recover function within days to weeks after surgery.', 'Easy', 47, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 55-year-old woman has a serum calcium of 11.6 mg/dL, parathyroid hormone of 145 pg/mL, and low serum phosphate. She has a history of kidney stones and dual-energy X-ray absorptiometry shows osteoporosis. Which of the following is the most likely diagnosis and definitive treatment?', '["Multiple myeloma treated with chemotherapy", "Vitamin D intoxication treated by stopping supplements", "Parathyroidectomy for primary hyperparathyroidism", "Start a thiazide diuretic", "Bisphosphonate therapy alone"]'::jsonb, 2, 'Hypercalcemia with an inappropriately high parathyroid hormone level, low phosphate, kidney stones, and bone loss is primary hyperparathyroidism, and parathyroidectomy is the definitive treatment for symptomatic disease. Multiple myeloma causes hypercalcemia with suppressed parathyroid hormone, not elevated levels. Vitamin D intoxication also suppresses parathyroid hormone. Thiazide diuretics raise serum calcium and would worsen the problem. Bisphosphonates lower calcium only temporarily and do not cure the underlying parathyroid adenoma. Asymptomatic patients with mild hypercalcemia may be observed, but stones, osteoporosis, or a calcium above 11.5 mg/dL all favor surgical removal of the adenoma.', 'Medium', 48, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 66-year-old man with stage 5 chronic kidney disease not yet on dialysis has a serum bicarbonate of 15 mEq/L, an anion gap of 21, and a pH of 7.30. He has no ketones, a normal lactate, and a potassium of 5.4 mEq/L. Which of the following is the most appropriate next step?', '["Give intravenous insulin", "Give a high-dose loop diuretic", "Increase dietary protein intake", "Give oral sodium bicarbonate", "Start immediate hemodialysis"]'::jsonb, 3, 'Uremic metabolic acidosis with a low bicarbonate is treated with oral sodium bicarbonate, which guidelines recommend when bicarbonate is below 22 mEq/L to slow chronic kidney disease progression and improve bone health. Insulin treats hyperkalemia and diabetic ketoacidosis, neither of which is present here. Diuretics do not correct uremic acidosis. Increasing dietary protein raises the acid load and worsens acidosis. Dialysis is not yet indicated without refractory acidosis or uremic symptoms. Sodium bicarbonate also helps by reducing bone buffering of acid, which protects bone mineral density in patients with chronic kidney disease.', 'Medium', 49, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 58-year-old man with long-standing diabetes mellitus has a potassium of 5.9 mEq/L, bicarbonate of 17 mEq/L, anion gap of 10, and chloride of 112 mEq/L. His urine pH is 6.2 and eGFR is 45 mL/min/1.73 m². Which of the following is the most likely diagnosis?', '["Type 1 renal tubular acidosis", "Type 2 renal tubular acidosis", "Diabetic ketoacidosis", "Lactic acidosis", "Type 4 renal tubular acidosis"]'::jsonb, 4, 'Diabetes with hyperkalemia and a normal anion gap hyperchloremic metabolic acidosis is classic type 4 renal tubular acidosis from hyporeninemic hypoaldosteronism. Type 1 renal tubular acidosis causes hypokalemia with alkaline urine and kidney stones, not hyperkalemia. Type 2 renal tubular acidosis also causes hypokalemia with bicarbonaturia. Diabetic ketoacidosis produces a high anion gap with ketones, which are absent here. Lactic acidosis raises the anion gap, but this patient''s gap is normal at 10. Management focuses on dietary potassium restriction, loop diuretics, and sometimes fludrocortisone, while avoiding drugs that raise potassium further.', 'Hard', 50, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 60-year-old woman has had vomiting for 5 days after gastroenteritis. Her bicarbonate is 34 mEq/L, chloride is 88 mEq/L, potassium is 3.1 mEq/L, and pH is 7.52. She is volume depleted on examination. Which of the following is the most appropriate treatment?', '["Give isotonic saline", "Give acetazolamide", "Give intravenous potassium chloride alone", "Give hydrochlorothiazide", "Give sodium bicarbonate"]'::jsonb, 0, 'Prolonged vomiting causes chloride-responsive metabolic alkalosis from gastric acid loss and volume contraction, and isotonic saline restores volume and chloride so the kidney can excrete bicarbonate. Acetazolamide is used for chloride-resistant alkalosis, not for vomiting-induced alkalosis. Potassium replacement alone does not correct the chloride deficit. Thiazide diuretics worsen metabolic alkalosis by increasing bicarbonate reabsorption. Sodium bicarbonate would further raise the bicarbonate and worsen the alkalosis. Potassium repletion is also needed, since hypokalemia maintains the alkalosis by increasing bicarbonate reabsorption in the proximal tubule, and chloride is the key ion the kidney needs to excrete the excess bicarbonate.', 'Easy', 51, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 70-year-old man taking furosemide for heart failure has a bicarbonate of 32 mEq/L, potassium of 3.0 mEq/L, and chloride of 90 mEq/L, and he is volume depleted. Which of the following is the most appropriate next step?', '["Increase the furosemide dose", "Stop furosemide, replace potassium, and give isotonic saline", "Start acetazolamide", "Give intravenous sodium bicarbonate", "Give spironolactone alone"]'::jsonb, 1, 'Loop diuretics cause contraction alkalosis with chloride and potassium loss, so the correct treatment is to stop the diuretic and replace chloride and potassium with isotonic saline and potassium chloride. Increasing furosemide would worsen the alkalosis and electrolyte losses. Acetazolamide is not first-line treatment for diuretic-induced alkalosis. Sodium bicarbonate would worsen the alkalosis. Spironolactone alone does not replace the chloride deficit. Once the diuretic is stopped and volume and chloride are restored, the kidney can excrete the excess bicarbonate and the pH normalizes, which is why replacing chloride is more important than simply giving alkali.', 'Medium', 52, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 68-year-old woman who has taken omeprazole daily for 3 years presents with muscle cramps and weakness. Her magnesium is 1.1 mg/dL, potassium is 3.0 mEq/L, and calcium is 7.9 mg/dL. Her hypokalemia has been refractory to potassium replacement. Which of the following is the most appropriate next step?', '["Increase oral potassium replacement only", "Give intravenous calcium gluconate", "Stop omeprazole and give intravenous magnesium sulfate", "Start a thiazide diuretic", "Give oral phosphate repletion"]'::jsonb, 2, 'Chronic proton pump inhibitor use impairs intestinal magnesium absorption, causing hypomagnesemia with secondary hypokalemia and hypocalcemia, so stopping the proton pump inhibitor and repleting magnesium corrects all three abnormalities. Potassium replacement alone fails while magnesium remains low. Calcium gluconate does not address the magnesium deficit. Thiazide diuretics worsen magnesium and potassium losses. Phosphate repletion is irrelevant to this patient''s problem. Magnesium is a cofactor for the sodium-potassium pump, so deficiency causes both potassium and calcium to fall, and all three correct only after magnesium is restored.', 'Medium', 53, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 55-year-old malnourished man was started on total parenteral nutrition 3 days ago and now has a serum phosphate of 1.3 mg/dL, potassium of 3.1 mEq/L, and magnesium of 1.2 mg/dL, with confusion and weakness. Which of the following is the most appropriate next step?', '["Increase the dextrose infusion rate", "Give intravenous insulin", "Continue feeds and add oral phosphate only", "Slow or hold nutrition, replete phosphate and thiamine, and monitor electrolytes", "Start hemodialysis"]'::jsonb, 3, 'Refeeding syndrome causes insulin-driven intracellular shifts of phosphate, potassium, and magnesium when nutrition is restarted in a malnourished patient, so feeding must be slowed or held while phosphate is repleted with thiamine and close electrolyte monitoring. Increasing the dextrose infusion worsens the intracellular shifts. Insulin drives even more phosphate into cells. Oral phosphate alone is too slow for severe symptomatic depletion. Hemodialysis does not treat refeeding syndrome. Thiamine is given before dextrose-containing feeds because thiamine deficiency can precipitate Wernicke encephalopathy when carbohydrate metabolism suddenly increases.', 'Hard', 54, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 58-year-old man with sepsis has a pH of 7.28, bicarbonate of 14 mEq/L, pCO2 of 30 mm Hg, sodium of 140 mEq/L, chloride of 104 mEq/L, and lactate of 6.5 mmol/L. Which of the following is the best interpretation of his acid-base status?', '["Normal anion gap metabolic acidosis", "Respiratory acidosis", "Metabolic alkalosis", "Mixed metabolic and respiratory acidosis", "High anion gap metabolic acidosis with appropriate respiratory compensation"]'::jsonb, 4, 'The anion gap is 22 (140 minus 104 minus 14), a high anion gap acidosis caused by lactate, and Winter''s formula predicts a pCO2 of 29 plus or minus 2 (1.5 times 14 plus 8), so a pCO2 of 30 shows appropriate respiratory compensation. The gap is high, not normal. The low pH is metabolic in origin, not respiratory. There is no metabolic alkalosis, and the pCO2 is not inappropriately high, which rules out a mixed respiratory acidosis. The lactate level confirms the cause, and treating the underlying sepsis with fluids and antibiotics is the definitive management of the acidosis.', 'Medium', 55, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 24-year-old woman presents with tinnitus and hyperventilation after an intentional overdose. Her pH is 7.46, bicarbonate is 15 mEq/L, pCO2 is 22 mm Hg, and anion gap is 20. Her salicylate level is elevated. Which of the following is the best interpretation of her acid-base status?', '["High anion gap metabolic acidosis with primary respiratory alkalosis", "Isolated metabolic alkalosis", "Respiratory acidosis with metabolic compensation", "Normal anion gap metabolic acidosis", "High anion gap metabolic acidosis with appropriate respiratory compensation"]'::jsonb, 0, 'Salicylate poisoning causes a high anion gap metabolic acidosis together with a primary respiratory alkalosis from direct stimulation of the respiratory center. Winter''s formula predicts a pCO2 of 28 to 32 mm Hg for a bicarbonate of 15, but the actual pCO2 of 22 mm Hg is lower, proving an added respiratory alkalosis. Isolated metabolic alkalosis would show a high bicarbonate, not a low one. Respiratory acidosis raises pCO2 with a low pH. The anion gap is 20, not normal, and compensation is not appropriate because the pCO2 is below the predicted range.', 'Hard', 56, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 68-year-old man with chronic kidney disease has vomited for 3 days. His pH is 7.44, bicarbonate is 30 mEq/L, pCO2 is 46 mm Hg, sodium is 138 mEq/L, chloride is 88 mEq/L, and anion gap is 20. Which of the following is the best interpretation of his acid-base status?', '["Isolated metabolic alkalosis", "Combined high anion gap metabolic acidosis and metabolic alkalosis", "Respiratory acidosis", "Normal anion gap metabolic acidosis", "High anion gap metabolic acidosis with appropriate respiratory compensation"]'::jsonb, 1, 'The anion gap is 20, confirming a high anion gap acidosis from uremia, while the bicarbonate is elevated at 30 mEq/L from vomiting-related metabolic alkalosis, and the delta ratio is negative, indicating a mixed disorder rather than a single one. Isolated metabolic alkalosis would have a normal anion gap. Respiratory acidosis would show a low pH with high pCO2 as the primary change. The gap is high, not normal, and the bicarbonate is high rather than low, ruling out a simple compensated metabolic acidosis.', 'Hard', 57, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 48-year-old woman with Cushing syndrome has a blood pressure of 165/100 mm Hg, potassium of 2.9 mEq/L, bicarbonate of 32 mEq/L, and pH of 7.50. Which of the following is the most appropriate treatment for her metabolic alkalosis?', '["Give hydrochlorothiazide", "Give isotonic saline", "Give spironolactone", "Give acetazolamide", "Give potassium chloride alone"]'::jsonb, 2, 'Mineralocorticoid excess from Cushing syndrome causes chloride-resistant metabolic alkalosis with hypokalemia and hypertension, and spironolactone blocks the mineralocorticoid receptor, correcting both the alkalosis and the potassium loss. Thiazide diuretics worsen alkalosis and potassium loss. Isotonic saline treats chloride-responsive, not chloride-resistant, alkalosis. Acetazolamide is not first-line therapy for mineralocorticoid excess. Potassium replacement alone does not address the ongoing mineralocorticoid-driven renal potassium losses. Potassium chloride repletion is given alongside spironolactone, but potassium alone cannot keep up with the ongoing renal losses while the mineralocorticoid excess persists.', 'Medium', 58, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 62-year-old woman with stage 4 chronic kidney disease has a hemoglobin of 9.6 g/dL, ferritin of 420 ng/mL, and transferrin saturation of 32%. She has no bleeding and an eGFR of 24 mL/min/1.73 m². Which of the following is the most appropriate next step in managing her anemia?', '["Give a red blood cell transfusion", "Give oral iron", "Give intravenous iron", "Start an erythropoiesis-stimulating agent", "Stop the ACE inhibitor"]'::jsonb, 3, 'With iron stores replete, as shown by a ferritin of 420 ng/mL and transferrin saturation of 32%, anemia in chronic kidney disease is caused by erythropoietin deficiency, and an erythropoiesis-stimulating agent is indicated after iron repletion. Red cell transfusion is reserved for symptomatic or severe anemia. Oral or intravenous iron is unnecessary when iron stores are already replete. Stopping the ACE inhibitor does not treat anemia and sacrifices renoprotection. The target hemoglobin is usually 10 to 11.5 g/dL, and higher targets are avoided because they increase the risk of stroke and thrombosis.', 'Medium', 59, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 55-year-old man on peritoneal dialysis presents with cloudy dialysate, abdominal pain, and a fever of 38.5°C. His effluent white blood cell count is 450 cells/µL with 80% neutrophils. Which of the following is the most appropriate next step?', '["Give oral amoxicillin", "Remove the peritoneal dialysis catheter immediately", "Give intravenous vancomycin alone", "Observe and repeat the effluent cell count in 48 hours", "Obtain effluent cultures and give intraperitoneal vancomycin plus ceftazidime"]'::jsonb, 4, 'Cloudy effluent with abdominal pain and a neutrophilic pleocytosis is peritoneal dialysis peritonitis, and effluent cultures followed by intraperitoneal antibiotics covering gram-positive and gram-negative organisms are first-line treatment. Oral amoxicillin lacks adequate coverage for peritonitis. Catheter removal is reserved for refractory, fungal, or relapsing peritonitis. Intravenous vancomycin alone misses gram-negative coverage. Observation risks sepsis and permanent peritoneal membrane failure. Treatment usually continues for two to three weeks, and the catheter is removed only if the infection is refractory, fungal, or relapsing despite appropriate antibiotics.', 'Medium', 60, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 42-year-old man presents with 3 weeks of progressive periorbital and lower-extremity edema and foamy urine. Blood pressure is 138/88 mmHg. Urinalysis shows 4+ protein, oval fat bodies, and fatty casts, with no red blood cells. Serum albumin is 2.4 g/dL, total cholesterol is 320 mg/dL, and serum creatinine is 1.0 mg/dL. A 24-hour urine collection shows 5.2 g of protein. Which of the following best describes the mechanism of the hypercoagulability seen in this patient''s condition?', '["Urinary loss of antithrombin III and increased hepatic synthesis of clotting factors", "Platelet destruction from circulating immune complexes", "Deficiency of protein C caused by hepatic synthetic failure", "Activation of the fibrinolytic system by hypoalbuminemia", "Increased von Willebrand factor from endothelial injury"]'::jsonb, 0, 'This patient has nephrotic syndrome, defined by proteinuria greater than 3.5 g/day, hypoalbuminemia, edema, hyperlipidemia, and lipiduria with fatty casts. Hypercoagulability in nephrotic syndrome results from urinary loss of antithrombin III, a small anticoagulant protein, combined with increased hepatic synthesis of procoagulant factors such as fibrinogen in response to hypoalbuminemia. Platelet destruction from immune complexes is not the mechanism here. Protein C deficiency from hepatic failure is incorrect because the liver is functioning and overproducing proteins, not failing. Fibrinolysis is impaired, not activated, in nephrotic syndrome. Von Willebrand factor is not the primary driver of the thrombotic risk.', 'Medium', 61, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 28-year-old woman with nephrotic syndrome due to membranous nephropathy presents with sudden onset of severe left flank pain, gross hematuria, and a rising serum creatinine. She has been taking furosemide and has been immobile at home for a week. Doppler ultrasound shows an enlarged left kidney with absent flow in the renal vein. Which of the following is the most appropriate next step in management?', '["Start high-dose corticosteroids immediately", "Obtain a renal biopsy to confirm the diagnosis", "Start therapeutic anticoagulation with heparin", "Increase the dose of furosemide and restrict fluids", "Start broad-spectrum antibiotics for pyelonephritis"]'::jsonb, 2, 'This patient has a renal vein thrombosis, a classic complication of nephrotic syndrome, especially membranous nephropathy, presenting with flank pain, hematuria, and worsening renal function. Therapeutic anticoagulation with heparin is the urgent treatment to prevent clot extension and pulmonary embolism. High-dose corticosteroids treat the underlying glomerular disease but do not address the acute thrombosis. Renal biopsy is unnecessary and unsafe in the setting of acute thrombosis and anticoagulation needs. Increasing furosemide would worsen volume depletion and clotting risk. Antibiotics are not indicated, as this is a thrombotic, not infectious, process.', 'Medium', 62, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 55-year-old man with nephrotic syndrome is admitted with fever, chills, and a productive cough. Blood cultures grow Streptococcus pneumoniae. He has no history of splenectomy. Which of the following best explains his increased susceptibility to this infection?', '["Urinary loss of immunoglobulins and complement factors", "Neutropenia caused by chronic corticosteroid use", "Impaired mucociliary clearance from hypoalbuminemia", "Functional asplenia from renal vein thrombosis", "Complement activation by circulating immune complexes"]'::jsonb, 0, 'Patients with nephrotic syndrome are at increased risk of infection with encapsulated organisms such as Streptococcus pneumoniae because of urinary loss of immunoglobulins and complement factors, particularly factor B of the alternative pathway, impairing opsonization. This patient has not received corticosteroids, so steroid-induced neutropenia does not apply. Hypoalbuminemia does not impair mucociliary clearance. Functional asplenia is not a feature of nephrotic syndrome or renal vein thrombosis. Complement activation by immune complexes describes a mechanism of glomerular injury, not the cause of infection susceptibility in this setting.', 'Hard', 63, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 16-year-old boy presents with 2 days of periorbital edema, gross hematuria described as cola-colored urine, and a blood pressure of 150/95 mmHg. He had a sore throat 2 weeks ago. Urinalysis shows dysmorphic red blood cells and red blood cell casts, with 2+ protein. Serum creatinine is 1.4 mg/dL. Which of the following findings best distinguishes this syndrome from nephrotic syndrome?', '["Presence of hypoalbuminemia and hyperlipidemia", "Presence of dysmorphic red blood cells and red blood cell casts", "Proteinuria greater than 3.5 g per day", "Presence of oval fat bodies and fatty casts", "Severe edema with normal blood pressure"]'::jsonb, 1, 'This patient has nephritic syndrome, characterized by hematuria with dysmorphic red blood cells and red blood cell casts, hypertension, azotemia, and subnephrotic proteinuria. Dysmorphic red blood cells and red blood cell casts indicate glomerular bleeding and are the hallmark distinguishing nephritic from nephrotic syndrome. Hypoalbuminemia, hyperlipidemia, heavy proteinuria above 3.5 g per day, and fatty casts are all features of nephrotic syndrome, not nephritic syndrome. Nephritic syndrome typically presents with hypertension and modest edema, not the severe anasarca with normal blood pressure seen in nephrotic syndrome.', 'Easy', 64, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 34-year-old woman presents with dark urine, facial swelling, and a blood pressure of 160/100 mmHg. Urinalysis reveals red blood cell casts and 1.5 g/day of protein. Serum creatinine is 1.8 mg/dL and serum C3 is low. Which of the following is the most appropriate initial management?', '["Sodium restriction, loop diuretics, and blood pressure control", "High-dose prednisone and cyclophosphamide", "Plasmapheresis and high-dose corticosteroids", "Anticoagulation with low-molecular-weight heparin", "Immediate renal biopsy without supportive measures"]'::jsonb, 0, 'This patient has nephritic syndrome, likely post-streptococcal glomerulonephritis given the low C3. Initial management is supportive: sodium restriction, loop diuretics for volume overload and edema, and blood pressure control, since the disease is usually self-limited. High-dose prednisone and cyclophosphamide are reserved for rapidly progressive glomerulonephritis or lupus nephritis, not uncomplicated post-infectious disease. Plasmapheresis is indicated for anti-GBM disease, not post-streptococcal glomerulonephritis. Anticoagulation is not indicated without thrombosis. Renal biopsy is not required when the clinical picture is classic and the disease course is expected to resolve spontaneously.', 'Medium', 65, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 5-year-old boy presents with sudden onset of periorbital edema and foamy urine 1 week after an upper respiratory infection. Blood pressure is 105/70 mmHg. Urinalysis shows 4+ protein with no red blood cells or casts. Serum albumin is 2.1 g/dL, cholesterol is 310 mg/dL, and creatinine is 0.5 mg/dL. Renal ultrasound is normal. Which of the following is the most likely diagnosis and the most appropriate initial treatment?', '["Minimal change disease; high-dose oral prednisone", "Focal segmental glomerulosclerosis; cyclosporine", "Membranous nephropathy; rituximab", "IgA nephropathy; ACE inhibitor", "Post-streptococcal glomerulonephritis; supportive care"]'::jsonb, 0, 'This child has classic minimal change disease, the most common cause of nephrotic syndrome in children, presenting with abrupt-onset edema, heavy selective proteinuria, hypoalbuminemia, and hyperlipidemia with a bland urinary sediment and normal renal function. It is exquisitely steroid-responsive, so high-dose oral prednisone is the first-line treatment, and biopsy is usually deferred. Focal segmental glomerulosclerosis is often steroid-resistant and presents in older patients. Membranous nephropathy is rare in children. IgA nephropathy causes hematuria, not isolated nephrotic syndrome. Post-streptococcal glomerulonephritis causes nephritic, not nephrotic, features with hematuria and low complement.', 'Medium', 66, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 7-year-old girl with nephrotic syndrome is treated with 8 weeks of high-dose prednisone with complete remission, but she relapses twice within 6 months of tapering. Her renal function remains normal and urinalysis between relapses is normal. Which of the following is the most appropriate next step in management?', '["Continue prednisone indefinitely at the same dose", "Add a steroid-sparing agent such as cyclophosphamide or rituximab", "Perform a renal biopsy to exclude focal segmental glomerulosclerosis", "Start an ACE inhibitor and stop all immunosuppression", "Restrict dietary protein to less than 0.5 g/kg per day"]'::jsonb, 1, 'This child has frequently relapsing minimal change disease, defined by two or more relapses within 6 months. The appropriate next step is a steroid-sparing agent such as cyclophosphamide, rituximab, or a calcineurin inhibitor to maintain remission while reducing cumulative steroid toxicity. Continuing high-dose prednisone indefinitely causes unacceptable growth suppression, cataracts, and bone toxicity. Renal biopsy is reserved for steroid-resistant disease or atypical features, not for steroid-sensitive frequent relapsers. An ACE inhibitor reduces proteinuria but does not prevent relapses. Severe dietary protein restriction is not recommended and does not treat the underlying immune-mediated podocyte injury.', 'Hard', 67, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 38-year-old African American man with HIV presents with nephrotic-range proteinuria of 6 g/day, a serum creatinine of 2.1 mg/dL, and a normal-sized kidney on ultrasound. Urinalysis shows no red blood cell casts. Renal biopsy reveals segmental sclerosis of glomeruli with collapsing features and tubular microcysts. Which of the following is the most likely diagnosis?', '["Minimal change disease", "Focal segmental glomerulosclerosis, collapsing variant", "Membranous nephropathy", "Diabetic nephropathy", "Amyloidosis"]'::jsonb, 1, 'This patient has collapsing focal segmental glomerulosclerosis, the classic HIV-associated nephropathy seen in African American patients, characterized by heavy proteinuria, rapidly progressive renal failure, normal or enlarged kidneys, and biopsy showing collapsing glomerular tufts with tubular microcysts. Minimal change disease causes nephrotic syndrome but with normal light microscopy and preserved renal function. Membranous nephropathy shows thickened glomerular basement membranes with subepithelial deposits, not collapsing lesions. Diabetic nephropathy shows nodular glomerulosclerosis and requires long-standing diabetes. Amyloidosis shows Congo red-positive deposits, not segmental sclerosis.', 'Hard', 68, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 45-year-old man with obesity and a history of intravenous drug use presents with nephrotic syndrome and a serum creatinine of 1.9 mg/dL. Renal biopsy shows focal segmental glomerulosclerosis. Which of the following is the most appropriate initial management?', '["High-dose corticosteroids and cyclophosphamide", "ACE inhibitor, blood pressure control, weight loss, and sodium restriction", "Rituximab and plasmapheresis", "Immediate initiation of hemodialysis", "Anticoagulation with warfarin"]'::jsonb, 1, 'This patient has secondary focal segmental glomerulosclerosis from obesity-related hyperfiltration and possibly heroin-associated nephropathy, which is driven by glomerular hypertension and does not respond to immunosuppression. Management is supportive: ACE inhibitors to reduce intraglomerular pressure and proteinuria, blood pressure control, weight loss, and sodium restriction. High-dose corticosteroids and cyclophosphamide are used for primary focal segmental glomerulosclerosis, not secondary disease, and carry significant toxicity without benefit here. Rituximab and plasmapheresis are not indicated. Dialysis is premature with a creatinine of 1.9 mg/dL. Anticoagulation is not indicated without a thrombotic event.', 'Medium', 69, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 58-year-old man presents with 2 months of progressive leg edema and foamy urine. Urinalysis shows 4+ protein and fatty casts without red blood cells. Serum albumin is 2.6 g/dL and creatinine is 1.1 mg/dL. Serologic testing is positive for anti-phospholipase A2 receptor antibodies. Renal biopsy shows thickened glomerular basement membranes with subepithelial immune deposits and no cellular proliferation. Which of the following is the most likely diagnosis?', '["Primary membranous nephropathy", "Minimal change disease", "IgA nephropathy", "Diabetic nephropathy", "Focal segmental glomerulosclerosis"]'::jsonb, 0, 'This patient has primary membranous nephropathy, the most common cause of nephrotic syndrome in adults. The positive anti-PLA2R antibody is highly specific for primary disease, and biopsy shows the classic thickened glomerular basement membrane with subepithelial immune deposits and a paucity of cellular proliferation. Minimal change disease has normal light microscopy and no immune deposits. IgA nephropathy presents with hematuria and mesangial IgA deposits. Diabetic nephropathy shows Kimmelstiel-Wilson nodules and requires long-standing diabetes. Focal segmental glomerulosclerosis shows segmental scarring rather than diffuse basement membrane thickening.', 'Medium', 70, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 67-year-old man is diagnosed with membranous nephropathy on renal biopsy. Anti-PLA2R antibodies are negative. He has a 40 pack-year smoking history and reports a 10-pound unintentional weight loss over 3 months. Which of the following is the most appropriate next step in management?', '["Perform age-appropriate malignancy screening", "Start high-dose prednisone and cyclophosphamide", "Initiate plasmapheresis", "Refer for kidney transplant evaluation", "Start rituximab without further workup"]'::jsonb, 0, 'Secondary membranous nephropathy is associated with malignancy, autoimmune diseases such as lupus, and medications. In an older patient with new-onset nephrotic syndrome from membranous nephropathy, age-appropriate cancer screening is essential, since an occult solid tumor, particularly lung, prostate, or colon cancer, may be driving the disease. High-dose corticosteroids are first-line for primary membranous nephropathy, but secondary disease requires treating the underlying cause. Plasmapheresis has no role. A kidney transplant is not indicated with preserved renal function. Starting immunosuppression without screening would delay diagnosis of a potentially treatable malignancy.', 'Medium', 71, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 49-year-old man with primary membranous nephropathy has persistent nephrotic syndrome with 8 g/day of proteinuria, a rising serum creatinine from 1.1 to 1.8 mg/dL, and a high anti-PLA2R antibody titer. He is already on an ACE inhibitor. Which of the following is the most appropriate first-line immunosuppressive therapy?', '["High-dose corticosteroids alone", "ACE inhibitor alone", "Rituximab", "Cyclosporine as first-line therapy", "Watchful waiting with supportive care only"]'::jsonb, 2, 'This patient has high-risk primary membranous nephropathy with nephrotic syndrome, declining renal function, and high anti-PLA2R titers. Rituximab, a monoclonal antibody against CD20, is now the preferred first-line immunosuppressive therapy because it achieves immunologic remission with a favorable safety profile compared with cyclophosphamide. High-dose corticosteroids alone are ineffective in membranous nephropathy. ACE inhibitors reduce proteinuria and should be continued but do not induce remission. Cyclosporine is an alternative but has nephrotoxicity and high relapse rates. Watchful waiting is inappropriate with progressive renal dysfunction and high antibody titers.', 'Hard', 72, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 22-year-old man presents with gross hematuria 2 days after developing a sore throat and fever. He has mild flank discomfort and a blood pressure of 135/85 mmHg. Urinalysis shows dysmorphic red blood cells and 1 g/day of protein. Serum creatinine is 1.0 mg/dL and C3 is normal. Renal biopsy shows mesangial deposits of IgA on immunofluorescence. Which of the following is the most likely diagnosis?', '["Alport syndrome", "Lupus nephritis", "IgA nephropathy", "Post-streptococcal glomerulonephritis", "Minimal change disease"]'::jsonb, 2, 'IgA nephropathy is the most common primary glomerulonephritis worldwide and characteristically presents with episodes of gross hematuria occurring 1 to 2 days after an upper respiratory infection, a time course called synpharyngitic hematuria. Renal biopsy shows mesangial IgA deposits on immunofluorescence. Post-streptococcal glomerulonephritis presents 1 to 3 weeks after streptococcal infection, not 1 to 2 days. Minimal change disease causes nephrotic syndrome without hematuria. Alport syndrome causes hematuria but is hereditary with sensorineural hearing loss and ocular abnormalities. Lupus nephritis is associated with systemic lupus features and positive ANA and anti-dsDNA.', 'Easy', 73, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 30-year-old woman with biopsy-proven IgA nephropathy returns for follow-up. She has persistent proteinuria of 1.8 g/day despite 6 months of blood pressure control with a calcium channel blocker. Serum creatinine is 1.2 mg/dL. Which of the following is the most appropriate next step in management?', '["Start rituximab", "Perform a repeat renal biopsy", "Refer for tonsillectomy and plasmapheresis", "Start an ACE inhibitor and optimize blood pressure control", "Start high-dose corticosteroids immediately"]'::jsonb, 3, 'This patient has IgA nephropathy with persistent proteinuria above 1 g per day, which is the strongest predictor of progression to end-stage kidney disease. KDIGO guidelines recommend an ACE inhibitor or ARB to reduce proteinuria and slow progression, along with blood pressure control and supportive care. High-dose corticosteroids are reserved for patients with persistent proteinuria despite maximal supportive therapy and are not first-line. Rituximab has no proven benefit in IgA nephropathy. Renal biopsy is already done. Tonsillectomy is not standard therapy, and plasmapheresis has no role in IgA nephropathy.', 'Medium', 74, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 9-year-old boy presents 2 weeks after a streptococcal sore throat with cola-colored urine, periorbital edema, and a blood pressure of 145/90 mmHg. Serum creatinine is 1.3 mg/dL. Urinalysis shows red blood cell casts. Laboratory studies show a low serum C3 with a normal C4. Which of the following is the most likely diagnosis?', '["Lupus nephritis", "Post-streptococcal glomerulonephritis", "IgA nephropathy", "Anti-GBM disease", "Membranous nephropathy"]'::jsonb, 1, 'Post-streptococcal glomerulonephritis is a classic post-infectious nephritic syndrome presenting 1 to 3 weeks after streptococcal pharyngitis with gross hematuria, periorbital edema, hypertension, and azotemia. Complement C3 is characteristically low due to activation of the alternative pathway, while C4 is normal. The disease is usually self-limited, and management is supportive with sodium restriction and diuretics. Lupus nephritis has low C3 and C4 with positive ANA and anti-dsDNA. IgA nephropathy has normal complement. Anti-GBM disease has linear IgG deposits and rapidly progressive renal failure. Membranous nephropathy causes nephrotic, not nephritic, syndrome.', 'Easy', 75, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 12-year-old girl presents 3 weeks after a streptococcal skin infection with hematuria, mild edema, and a blood pressure of 140/88 mmHg. Serum creatinine is 1.1 mg/dL and C3 is low. Which of the following is the most appropriate management?', '["Start high-dose corticosteroids and cyclophosphamide", "Provide supportive care with sodium restriction and diuretics and monitor complement levels", "Perform an urgent renal biopsy", "Initiate plasmapheresis", "Start anticoagulation with heparin"]'::jsonb, 1, 'Post-streptococcal glomerulonephritis is typically self-limited, with hematuria and renal function improving over weeks and C3 normalizing within 6 to 8 weeks. A normal C3 excludes most other causes of hypocomplementemia. High-dose corticosteroids and cyclophosphamide are reserved for rapidly progressive glomerulonephritis, not uncomplicated post-streptococcal disease. Renal biopsy is not required when the presentation is classic and improving. Plasmapheresis is indicated for anti-GBM disease. There is no role for anticoagulation. Reassurance and supportive care with monitoring are appropriate, with close follow-up of blood pressure, renal function, and complement levels.', 'Medium', 76, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 26-year-old woman with systemic lupus erythematosus presents with hematuria, proteinuria of 3.5 g/day, hypertension, and a serum creatinine of 1.9 mg/dL. Serology shows low C3 and C4 with a high anti-dsDNA titer. Renal biopsy shows diffuse proliferative glomerulonephritis with subendothelial immune deposits. Which of the following is the most appropriate initial treatment?', '["Rituximab as first-line therapy", "Plasmapheresis and corticosteroids", "Hydroxychloroquine alone", "High-dose corticosteroids plus mycophenolate mofetil", "Supportive care with an ACE inhibitor alone"]'::jsonb, 3, 'This patient has lupus nephritis, class IV diffuse proliferative disease, the most common and severe form, presenting with nephritic features, low C3 and C4, and positive anti-dsDNA. Induction therapy with high-dose corticosteroids plus mycophenolate mofetil or cyclophosphamide is required to achieve remission and prevent progression to end-stage kidney disease. Supportive care alone is inadequate for proliferative lupus nephritis. Rituximab is reserved for refractory disease. Plasmapheresis is used for anti-GBM disease or severe pulmonary hemorrhage. Hydroxychloroquine is important background therapy but is not sufficient as induction treatment for class IV disease.', 'Medium', 77, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 34-year-old woman with a 5-year history of systemic lupus erythematosus presents with new-onset nephrotic syndrome with 5 g/day of proteinuria. Serum creatinine is 1.0 mg/dL, ANA and anti-dsDNA are positive, and C3 is low. Renal biopsy shows thickened glomerular basement membranes with subepithelial immune deposits and a full-house immunofluorescence pattern. Which of the following is the most likely diagnosis?', '["Primary membranous nephropathy", "Minimal change disease", "Class V membranous lupus nephritis", "Focal segmental glomerulosclerosis", "Diabetic nephropathy"]'::jsonb, 2, 'Class V membranous lupus nephritis presents with nephrotic syndrome and subepithelial immune deposits on biopsy, mimicking primary membranous nephropathy, but in the setting of systemic lupus with positive ANA, anti-dsDNA, and low complement. Treatment is immunosuppression with corticosteroids and mycophenolate mofetil for nephrotic-range proteinuria. Primary membranous nephropathy would have positive anti-PLA2R and no lupus serologies. Minimal change disease has normal light microscopy and no immune deposits. Focal segmental glomerulosclerosis shows segmental scarring. Diabetic nephropathy requires long-standing diabetes and shows Kimmelstiel-Wilson nodules, not subepithelial deposits.', 'Hard', 78, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 55-year-old man presents with 6 weeks of sinus congestion, epistaxis, cough with hemoptysis, and hematuria. Serum creatinine is 3.2 mg/dL. Urinalysis shows red blood cell casts. c-ANCA is positive with anti-PR3 antibodies. Renal biopsy shows crescentic glomerulonephritis with few immune deposits. Which of the following is the most likely diagnosis?', '["Anti-GBM disease", "Post-streptococcal glomerulonephritis", "ANCA-associated vasculitis", "IgA nephropathy", "Membranous nephropathy"]'::jsonb, 2, 'This patient has ANCA-associated vasculitis, specifically granulomatosis with polyangiitis, given the sinus disease, epistaxis, pulmonary hemorrhage, pauci-immune glomerulonephritis with crescents, and positive c-ANCA with anti-PR3 antibodies. Renal biopsy in ANCA vasculitis shows a pauci-immune pattern with few or no immune deposits, distinguishing it from lupus or immune-complex disease. Anti-GBM disease shows linear IgG deposits along the basement membrane. Post-streptococcal glomerulonephritis shows subepithelial humps with low C3. IgA nephropathy shows mesangial IgA deposits. Membranous nephropathy shows subepithelial deposits with nephrotic syndrome, not crescents and pulmonary hemorrhage.', 'Hard', 79, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 62-year-old woman presents with fatigue, arthralgias, hemoptysis, and rapidly rising creatinine to 2.8 mg/dL. Urinalysis shows red blood cell casts. p-ANCA is positive with anti-myeloperoxidase antibodies. Chest imaging shows bilateral alveolar infiltrates. Which of the following is the most appropriate initial treatment?', '["Broad-spectrum antibiotics", "High-dose corticosteroids alone", "High-dose corticosteroids plus rituximab or cyclophosphamide", "Plasmapheresis and supportive care", "ACE inhibitor alone"]'::jsonb, 2, 'This patient has microscopic polyangiitis, an ANCA-associated vasculitis with p-ANCA and anti-myeloperoxidase antibodies, presenting with pauci-immune crescentic glomerulonephritis and pulmonary involvement without upper airway disease. The absence of sinus or ear disease distinguishes microscopic polyangiitis from granulomatosis with polyangiitis. Remission induction requires high-dose corticosteroids plus rituximab or cyclophosphamide. Corticosteroids alone are insufficient for organ-threatening disease. Plasmapheresis is reserved for severe alveolar hemorrhage or dialysis-dependent renal failure, not first-line here. An ACE inhibitor alone does not treat vasculitis. Antibiotics are inappropriate since this is an autoimmune, not infectious, process.', 'Medium', 80, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 48-year-old woman with a 10-year history of asthma presents with new-onset mononeuritis multiplex, palpable purpura, and hematuria. Laboratory studies show marked peripheral eosinophilia and a positive p-ANCA. Urinalysis shows red blood cell casts and a serum creatinine of 1.6 mg/dL. Which of the following is the most likely diagnosis?', '["Polyarteritis nodosa", "Cryoglobulinemic vasculitis", "Granulomatosis with polyangiitis", "Eosinophilic granulomatosis with polyangiitis", "Microscopic polyangiitis"]'::jsonb, 3, 'This patient has eosinophilic granulomatosis with polyangiitis, formerly Churg-Strauss syndrome, an ANCA-associated vasculitis characterized by asthma, peripheral eosinophilia, and systemic vasculitis affecting the kidneys, lungs, and nerves. Pulmonary infiltrates and eosinophilia distinguish it from granulomatosis with polyangiitis, which has upper airway disease and c-ANCA rather than asthma and marked eosinophilia. Microscopic polyangiitis lacks asthma and eosinophilia. Polyarteritis nodosa affects medium vessels and spares the lungs and glomeruli. Cryoglobulinemia causes palpable purpura and low complement, not asthma with eosinophilia, and it is typically associated with hepatitis C infection.', 'Medium', 81, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 28-year-old man presents with hemoptysis, dyspnea, and rapidly rising creatinine to 4.5 mg/dL over 2 weeks. Urinalysis shows red blood cell casts. Renal biopsy reveals crescentic glomerulonephritis with linear IgG deposition along the glomerular basement membrane. Anti-GBM antibodies are positive. Which of the following is the most likely diagnosis?', '["Lupus nephritis", "IgA nephropathy", "Post-streptococcal glomerulonephritis", "Anti-GBM disease", "ANCA-associated vasculitis"]'::jsonb, 3, 'Anti-GBM disease, or Goodpasture syndrome, is caused by autoantibodies against type IV collagen in the glomerular and alveolar basement membranes, producing rapidly progressive crescentic glomerulonephritis with linear IgG deposition on immunofluorescence and alveolar hemorrhage. The combination of pulmonary hemorrhage and rapidly progressive renal failure with linear staining is diagnostic. ANCA vasculitis shows pauci-immune staining with few deposits. Lupus nephritis shows a full-house pattern with multiple immunoglobulins and complement. IgA nephropathy shows mesangial IgA deposits. Post-streptococcal glomerulonephritis shows granular deposits with subepithelial humps and low C3, not linear IgG staining.', 'Medium', 82, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 35-year-old man presents with hemoptysis, bilateral pulmonary infiltrates, and a creatinine of 6.8 mg/dL requiring dialysis. Anti-GBM antibodies are strongly positive. Which of the following is the most appropriate initial treatment?', '["Hemodialysis alone", "Observation and supportive care", "High-dose corticosteroids alone", "Plasmapheresis plus high-dose corticosteroids and cyclophosphamide", "Rituximab alone"]'::jsonb, 3, 'This patient has anti-GBM disease with dialysis-dependent renal failure and alveolar hemorrhage, the most severe presentation. Treatment requires urgent plasmapheresis to remove circulating anti-GBM antibodies, combined with high-dose corticosteroids and cyclophosphamide to suppress antibody production. Corticosteroids alone cannot remove existing antibodies quickly enough. Rituximab is not first-line for anti-GBM disease. Dialysis alone treats uremia but not the underlying immunologic process. Observation is inappropriate, as anti-GBM disease is rapidly fatal without aggressive immunotherapy, with irreversible renal failure if treatment is delayed.', 'Hard', 83, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 58-year-old man with type 2 diabetes mellitus for 15 years presents with progressive proteinuria of 2.5 g/day and a serum creatinine of 1.6 mg/dL. Fundoscopic examination shows proliferative diabetic retinopathy. Urine albumin-to-creatinine ratio is markedly elevated. Renal biopsy shows mesangial expansion with Kimmelstiel-Wilson nodules. Which of the following is the most likely diagnosis?', '["Membranous nephropathy", "Amyloidosis", "Focal segmental glomerulosclerosis", "Diabetic nephropathy", "Minimal change disease"]'::jsonb, 3, 'Diabetic nephropathy begins with glomerular hyperfiltration, followed by microalbuminuria, then macroalbuminuria, and progressive decline in glomerular filtration rate. Kimmelstiel-Wilson nodules are the classic pathologic finding, and patients often have concurrent diabetic retinopathy, which supports the diagnosis. Screening is with urine albumin-to-creatinine ratio and estimated glomerular filtration rate. Focal segmental glomerulosclerosis shows segmental scarring and no nodules. Minimal change disease has normal light microscopy. Membranous nephropathy shows basement membrane thickening with subepithelial deposits. Amyloidosis shows Congo red-positive deposits, not nodular glomerulosclerosis.', 'Medium', 84, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 62-year-old man with type 2 diabetes mellitus for 12 years has a urine albumin-to-creatinine ratio of 450 mg/g and a serum creatinine of 1.5 mg/dL. His blood pressure is 145/90 mmHg and his HbA1c is 8.2%. Which of the following is the most appropriate next step in management?', '["Thiazide diuretic alone", "High-dose corticosteroids", "Hemodialysis", "Tight glycemic control alone", "ACE inhibitor plus an SGLT2 inhibitor"]'::jsonb, 4, 'This patient has diabetic kidney disease with albuminuria, which should be treated with an ACE inhibitor or ARB to reduce intraglomerular pressure and proteinuria, plus an SGLT2 inhibitor, which has proven renal and cardiovascular benefits in diabetic kidney disease independent of glycemic control. Tight glycemic control slows progression but is not sufficient alone once albuminuria is established. A thiazide diuretic lowers blood pressure but does not provide the same renoprotection. High-dose corticosteroids have no role in diabetic nephropathy. Hemodialysis is not indicated with a creatinine of 1.5 mg/dL and no uremic complications.', 'Medium', 85, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 45-year-old woman is newly diagnosed with type 2 diabetes mellitus. Which of the following is the recommended screening strategy for diabetic kidney disease?', '["24-hour urine protein collection every 5 years", "Serum creatinine alone every 2 years", "Renal ultrasound annually", "Renal biopsy at the time of diabetes diagnosis", "Annual urine albumin-to-creatinine ratio and estimated glomerular filtration rate, starting 5 years after diagnosis in type 1 diabetes and at diagnosis in type 2 diabetes"]'::jsonb, 4, 'Annual screening for diabetic kidney disease should begin 5 years after diagnosis in type 1 diabetes and at diagnosis in type 2 diabetes, using a urine albumin-to-creatinine ratio and estimated glomerular filtration rate. Microalbuminuria is the earliest detectable marker of diabetic nephropathy and precedes overt proteinuria and declining renal function. A 24-hour urine protein collection is less sensitive for early disease. Serum creatinine alone is insensitive to early kidney damage. Renal ultrasound does not screen for diabetic nephropathy. Renal biopsy is not needed for screening and is reserved for atypical presentations.', 'Hard', 86, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 52-year-old man presents with severe headache, blurred vision, and a blood pressure of 230/140 mmHg. Fundoscopic examination shows papilledema and flame hemorrhages. Urinalysis shows hematuria and 1 g/day of protein. Serum creatinine is 2.4 mg/dL. Which of the following is the most appropriate initial management?', '["Immediate sublingual nifedipine", "Urgent renal biopsy", "High-dose corticosteroids", "Rapid reduction of blood pressure to normal within 1 hour", "Controlled blood pressure reduction with an intravenous antihypertensive agent"]'::jsonb, 4, 'This patient has malignant hypertension with severe blood pressure elevation, acute kidney injury, hematuria, and hypertensive retinopathy with papilledema. The most appropriate management is controlled reduction of blood pressure with an intravenous antihypertensive agent such as nicardipine or labetalol, targeting a modest reduction of about 25 percent in the first hours to avoid cerebral and renal hypoperfusion. Rapid normalization of blood pressure risks organ ischemia. Oral nifedipine causes unpredictable drops and is not recommended. A renal biopsy is not needed. High-dose corticosteroids have no role. Immediate hemodialysis is not indicated without refractory uremia or volume overload.', 'Medium', 87, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 65-year-old man with a 20-year history of poorly controlled hypertension presents with a serum creatinine of 2.0 mg/dL and a urine protein-to-creatinine ratio of 0.6 g/g. Urinalysis shows a bland sediment with few hyaline casts. Renal ultrasound shows small, echogenic kidneys. Which of the following is the most likely diagnosis?', '["Diabetic nephropathy", "Minimal change disease", "IgA nephropathy", "Autosomal dominant polycystic kidney disease", "Hypertensive nephrosclerosis"]'::jsonb, 4, 'Hypertensive nephrosclerosis is the classic renal lesion of long-standing hypertension, characterized by hyaline arteriolosclerosis, ischemic glomerular changes, a bland urinary sediment with minimal proteinuria, and slowly progressive renal insufficiency. The key diagnostic clue is the history of poorly controlled hypertension with a bland sediment. Diabetic nephropathy requires diabetes and shows heavy proteinuria with Kimmelstiel-Wilson nodules. Minimal change disease causes nephrotic syndrome with normal light microscopy. IgA nephropathy presents with hematuria and mesangial IgA deposits. Polycystic kidney disease shows enlarged kidneys with multiple cysts on imaging.', 'Easy', 88, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 62-year-old man presents with nephrotic syndrome, macroglossia, and periorbital purpura. Serum protein electrophoresis shows a monoclonal lambda light chain. Echocardiogram shows thickened ventricular walls with a low-voltage electrocardiogram. Renal biopsy shows Congo red-positive deposits with apple-green birefringence under polarized light. Which of the following is the most likely diagnosis?', '["Diabetic nephropathy", "Minimal change disease", "Multiple myeloma cast nephropathy", "Focal segmental glomerulosclerosis", "AL amyloidosis"]'::jsonb, 4, 'This patient has AL amyloidosis, characterized by nephrotic syndrome with Congo red-positive amyloid deposits showing apple-green birefringence under polarized light, macroglossia, and a monoclonal light chain on serum protein electrophoresis. Amyloid deposition causes a non-dilated, thick-walled heart with a low-voltage electrocardiogram. Diabetic nephropathy shows Kimmelstiel-Wilson nodules and requires diabetes. Minimal change disease has normal light microscopy and no Congo red staining. Multiple myeloma cast nephropathy causes acute kidney injury with Bence Jones proteinuria but not Congo red-positive deposits or macroglossia. Focal segmental glomerulosclerosis shows segmental scarring, not amyloid deposits.', 'Hard', 89, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 70-year-old man with multiple myeloma presents with acute kidney injury with a creatinine of 4.2 mg/dL. Urine dipstick shows 1+ protein, but a 24-hour urine collection shows 2.5 g of protein, mostly Bence Jones protein. Urinalysis shows a bland sediment. Which of the following is the most appropriate treatment?', '["High-dose corticosteroids alone", "Renal biopsy before any treatment", "Hemodialysis alone", "Plasmapheresis", "Bortezomib-based chemotherapy with aggressive hydration"]'::jsonb, 4, 'Light chain cast nephropathy, or myeloma kidney, occurs when excess monoclonal free light chains precipitate with Tamm-Horsfall protein in the distal tubules, causing tubular obstruction and acute kidney injury. It presents with acute renal failure, Bence Jones proteinuria, and a bland sediment. Treatment focuses on rapidly reducing light chain production with chemotherapy such as bortezomib-based regimens and aggressive hydration. Plasmapheresis is not routinely effective. High-dose corticosteroids alone are insufficient. A renal biopsy is not required when the clinical picture is classic. Hemodialysis treats uremia but does not address the underlying light chain burden.', 'Hard', 90, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 32-year-old woman presents with recurrent kidney stones, muscle weakness, and fatigue. Labs show potassium 2.8 mEq/L, bicarbonate 16 mEq/L, chloride 112 mEq/L, and a normal anion gap metabolic acidosis. Urine pH is 6.5 despite systemic acidosis, and she has nephrocalcinosis on imaging. Which of the following is the most likely diagnosis?', '["Type 2 (proximal) renal tubular acidosis", "Type 4 renal tubular acidosis", "Bartter syndrome", "Liddle syndrome", "Type 1 (distal) renal tubular acidosis"]'::jsonb, 4, 'Type 1 (distal) RTA is caused by failure of the distal tubule to secrete hydrogen ions, producing a normal anion gap metabolic acidosis with an inappropriately alkaline urine pH above 5.5, hypokalemia, and nephrocalcinosis with recurrent calcium phosphate stones from chronic acidemia and hypercalciuria. Type 2 (proximal) RTA involves bicarbonate wasting with urine pH below 5.5 when acidosis is severe, plus Fanconi features such as phosphaturia and glycosuria. Type 4 RTA causes hyperkalemia, not hypokalemia, from aldosterone deficiency or resistance. Bartter syndrome causes a metabolic alkalosis, not acidosis. Liddle syndrome causes hypertension with hypokalemia and metabolic alkalosis from excess ENaC activity.', 'Medium', 91, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 6-year-old boy is evaluated for growth failure, polyuria, and rickets. Labs show a normal anion gap metabolic acidosis, hypokalemia, hypophosphatemia, glycosuria, and aminoaciduria. Urine pH is 5.0. Which of the following is the most appropriate next step in management?', '["Ammonium chloride loading test", "High-dose loop diuretics", "Sodium restriction and thiazide diuretics", "Immediate hemodialysis", "Oral bicarbonate and phosphate supplementation with vitamin D"]'::jsonb, 4, 'This child has type 2 (proximal) RTA with Fanconi syndrome, in which the proximal tubule fails to reabsorb bicarbonate, phosphate, glucose, and amino acids, causing acidosis, hypokalemia, hypophosphatemia, rickets, and growth failure; the urine pH can fall below 5.5 because distal acidification is intact. Management is replacement of the lost bicarbonate and phosphate plus active vitamin D to treat rickets. An ammonium chloride loading test evaluates distal acidification and is used for type 1 RTA, not Fanconi syndrome. Loop diuretics worsen electrolyte losses. Sodium restriction and thiazides are used for nephrolithiasis and Bartter-like disorders, not Fanconi syndrome. Hemodialysis is not indicated for chronic proximal RTA.', 'Hard', 92, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 68-year-old man with diabetes and chronic kidney disease presents with potassium 6.1 mEq/L and bicarbonate 18 mEq/L. He has a normal anion gap metabolic acidosis, urine pH 5.8, and a low transtubular potassium gradient. His medications include lisinopril and spironolactone. Which of the following is the most likely diagnosis?', '["Type 1 (distal) renal tubular acidosis", "Type 2 (proximal) renal tubular acidosis", "Acute interstitial nephritis", "Type 4 renal tubular acidosis", "Diabetic ketoacidosis"]'::jsonb, 3, 'Type 4 RTA is a hyperkalemic normal anion gap metabolic acidosis caused by aldosterone deficiency or resistance, classically seen in diabetic nephropathy with hyporeninemic hypoaldosteronism and worsened by ACE inhibitors and potassium-sparing diuretics; the low transtubular potassium gradient reflects impaired distal potassium secretion. Type 1 RTA causes hypokalemia with an inappropriately alkaline urine, not hyperkalemia. Type 2 RTA causes hypokalemia with bicarbonate wasting. Acute interstitial nephritis presents with eosinophiluria, rash, fever, and sterile pyuria rather than isolated hyperkalemic acidosis. Diabetic ketoacidosis causes a high anion gap acidosis with hyperglycemia and ketones, which are absent here.', 'Medium', 93, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 14-year-old boy presents with polyuria, polydipsia, muscle cramps, and growth delay. Blood pressure is 95/60 mm Hg. Labs show potassium 2.9 mEq/L, magnesium 1.4 mg/dL, calcium 11.2 mg/dL, metabolic alkalosis, and elevated plasma renin and aldosterone. Urinary calcium excretion is markedly elevated. Which of the following is the most likely diagnosis?', '["Gitelman syndrome", "Liddle syndrome", "Bartter syndrome", "Cushing syndrome", "Primary hyperaldosteronism"]'::jsonb, 2, 'Bartter syndrome is a defect in the thick ascending limb of Henle (NKCC2, ROMK, or chloride channels) causing salt wasting, hypokalemic metabolic alkalosis, hypercalciuria, and secondary hyperreninemic hyperaldosteronism with normal or low blood pressure; onset is typically in childhood with polyuria and growth delay. Gitelman syndrome involves the distal convoluted tubule, causing hypocalciuria and hypomagnesemia with later onset, and would not produce hypercalciuria. Liddle syndrome causes hypertension with low renin and aldosterone from constitutive ENaC activation. Cushing syndrome causes hypertension and hypokalemia but with hyperglycemia, central obesity, and suppressed ACTH or excess cortisol. Primary hyperaldosteronism causes hypertension with suppressed renin.', 'Hard', 94, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 22-year-old woman presents with recurrent muscle weakness, paresthesias, and carpopedal spasm. Blood pressure is 100/65 mm Hg. Labs show potassium 2.7 mEq/L, magnesium 1.3 mg/dL, metabolic alkalosis, and low urinary calcium excretion. She reports no diuretic or laxative use. Which of the following is the most likely diagnosis?', '["Bartter syndrome", "Thiazide diuretic abuse", "Gitelman syndrome", "Bulimia nervosa", "Renal tubular acidosis type 1"]'::jsonb, 2, 'Gitelman syndrome is a defect in the thiazide-sensitive sodium-chloride cotransporter of the distal convoluted tubule, presenting in adolescence or young adulthood with hypokalemic metabolic alkalosis, hypomagnesemia, and hypocalciuria, with normal or low blood pressure; tetany and weakness reflect hypomagnesemia and hypokalemia. Bartter syndrome causes hypercalciuria rather than hypocalciuria and typically presents earlier in childhood. Thiazide abuse would produce a similar pattern but the patient denies diuretic use and urine diuretic screening would be positive. Bulimia causes hypokalemic alkalosis but with normal magnesium and calcium excretion, plus dental and parotid findings. Type 1 RTA causes a normal anion gap metabolic acidosis, not alkalosis.', 'Medium', 95, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 9-year-old boy is evaluated for polyuria, nocturia, and failure to thrive. Labs show serum sodium 150 mEq/L, serum osmolality 315 mOsm/kg, and urine osmolality 120 mOsm/kg. After a water deprivation test, urine osmolality rises only to 180 mOsm/kg; after desmopressin administration, urine osmolality rises to 640 mOsm/kg. Which of the following is the most likely diagnosis?', '["Nephrogenic diabetes insipidus", "Central diabetes insipidus", "Primary polydipsia", "Syndrome of inappropriate antidiuretic hormone secretion", "Diabetes mellitus"]'::jsonb, 1, 'Central diabetes insipidus results from deficient ADH secretion, so the kidney cannot concentrate urine during water deprivation (urine osmolality remains low despite rising serum osmolality) but responds to exogenous desmopressin with a marked rise in urine osmolality, as seen here. Nephrogenic diabetes insipidus would show no response to desmopressin because the kidney is resistant to ADH. Primary polydipsia causes low serum osmolality from excess water intake, and urine concentrates normally after water deprivation. SIADH causes hyponatremia with concentrated urine, the opposite pattern. Diabetes mellitus causes hyperglycemia with osmotic diuresis and glycosuria, which are absent here.', 'Medium', 96, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 58-year-old man with bipolar disorder on long-term lithium presents with polyuria of 6 L per day and polydipsia. Labs show sodium 148 mEq/L and serum osmolality 308 mOsm/kg with dilute urine. After desmopressin administration, urine osmolality does not increase. Which of the following is the most appropriate next step in management?', '["Start intranasal desmopressin", "Restrict free water intake", "Start high-dose loop diuretics", "Discontinue lithium and give a thiazide diuretic with low-salt diet", "Give intravenous hypertonic saline"]'::jsonb, 3, 'This patient has nephrogenic diabetes insipidus from lithium, which impairs the kidney''s response to ADH by downregulating aquaporin channels; the failure of urine osmolality to rise after desmopressin confirms ADH resistance. Management is to stop lithium when feasible and use a thiazide diuretic with sodium restriction, which paradoxically reduces urine output by causing mild volume contraction and increasing proximal reabsorption. Desmopressin is ineffective in nephrogenic DI because the receptor pathway is resistant. Water restriction alone worsens hypernatremia and dehydration. Loop diuretics increase urine output and worsen the polyuria. Hypertonic saline is used for severe symptomatic hyponatremia, not hypernatremia from water loss.', 'Medium', 97, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 72-year-old woman with small cell lung cancer is found to have sodium 118 mEq/L, serum osmolality 248 mOsm/kg, urine osmolality 520 mOsm/kg, and urine sodium 55 mEq/L. She is clinically euvolemic with normal thyroid and adrenal function. She is alert with mild nausea. Which of the following is the most appropriate initial management?', '["Rapid correction with 3% hypertonic saline bolus", "Intravenous isotonic saline", "Fluid restriction", "Demeclocycline", "High-dose loop diuretics alone"]'::jsonb, 2, 'This patient has SIADH from ectopic ADH secretion by small cell lung cancer, with euvolemic hyponatremia, inappropriately concentrated urine, and elevated urine sodium despite normal thyroid and adrenal function. In a clinically stable patient with mild symptoms, first-line treatment is fluid restriction to create a negative free water balance. Rapid hypertonic saline is reserved for severe symptomatic hyponatremia with seizures, coma, or severe neurologic symptoms. Isotonic saline worsens hyponatremia in SIADH because the administered sodium is excreted while the water is retained. Demeclocycline is a second-line agent for refractory cases and carries nephrotoxicity. Loop diuretics alone are not first-line therapy for SIADH.', 'Medium', 98, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 64-year-old man is brought to the emergency department with confusion and a generalized seizure. Labs show sodium 112 mEq/L, serum osmolality 232 mOsm/kg, urine osmolality 480 mOsm/kg, and urine sodium 60 mEq/L. He is euvolemic. Which of the following is the most appropriate immediate management?', '["Fluid restriction alone", "Intravenous 3% hypertonic saline", "Intravenous 0.9% normal saline", "Oral salt tablets", "Intravenous furosemide"]'::jsonb, 1, 'Severe symptomatic hyponatremia with seizures requires urgent treatment with 3% hypertonic saline to raise serum sodium by 4 to 6 mEq/L over a few hours and stop the seizure, while limiting total correction to 10 to 12 mEq/L in 24 hours to avoid osmotic demyelination. Fluid restriction alone acts too slowly for a patient with active seizures. Isotonic saline worsens hyponatremia in SIADH because the kidney excretes the sodium and retains the water. Oral salt tablets are ineffective in an acutely seizing patient and act too slowly. Furosemide alone does not correct severe symptomatic hyponatremia and can cause dangerous volume and electrolyte shifts.', 'Medium', 99, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 48-year-old man with autosomal dominant polycystic kidney disease presents with sudden severe flank pain, gross hematuria, and fever. Blood pressure is 150/95 mm Hg. Examination shows palpable bilateral flank masses. CT shows multiple bilateral renal cysts, one of which is enlarged and hyperdense. Which of the following is the most likely cause of his acute presentation?', '["Cyst hemorrhage", "Renal cell carcinoma", "Acute pyelonephritis", "Nephrolithiasis", "Renal vein thrombosis"]'::jsonb, 0, 'Acute flank pain with gross hematuria in ADPKD is most often caused by cyst hemorrhage, in which a cyst bleeds into itself or the collecting system; CT typically shows a hyperdense cyst, and fever can accompany the hemorrhage. Renal cell carcinoma is a risk in ADPKD but is less common as a cause of acute hematuria with a hyperdense cyst and would usually appear as a solid enhancing mass. Acute pyelonephritis causes fever and flank pain but usually with dysuria, pyuria, and bacteriuria rather than gross hematuria with a hyperdense cyst. Nephrolithiasis can cause hematuria and flank pain but CT would show a calcified stone. Renal vein thrombosis is more typical of nephrotic syndrome and presents with flank pain and hematuria but without a hyperdense cyst.', 'Medium', 100, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 35-year-old woman with autosomal dominant polycystic kidney disease asks about screening for complications. She has a father who died of a subarachnoid hemorrhage at age 45. She has no neurologic symptoms. Which of the following is the most appropriate screening recommendation?', '["Magnetic resonance angiography of the brain", "Annual abdominal ultrasound", "Annual echocardiogram", "Screening colonoscopy now", "Annual urine protein-to-creatinine ratio only"]'::jsonb, 0, 'Patients with ADPKD have an increased risk of intracranial berry aneurysms, and screening with magnetic resonance angiography is recommended when there is a family history of aneurysm or subarachnoid hemorrhage, as in this patient whose father died of one at a young age. Annual abdominal ultrasound monitors kidney size and cyst burden but does not address the aneurysm risk. Echocardiography screens for mitral valve prolapse and aortic root dilatation, which are less urgent than aneurysm screening here. Colonoscopy follows standard age-based screening and is not ADPKD-specific. Urine protein monitoring is part of routine CKD care but does not screen for the life-threatening extrarenal complication posed by her family history.', 'Medium', 101, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 52-year-old man with autosomal dominant polycystic kidney disease has an estimated glomerular filtration rate of 55 mL/min/1.73 m2 and rapidly increasing total kidney volume. His blood pressure is well controlled. Which of the following is the most appropriate therapy to slow progression of his kidney disease?', '["High-dose angiotensin receptor blocker", "Long-term antibiotics", "Sodium bicarbonate", "Tolvaptan", "Erythropoietin"]'::jsonb, 3, 'Tolvaptan, a vasopressin V2 receptor antagonist, slows the growth of kidney cysts and the decline in kidney function in ADPKD patients at high risk of rapid progression, such as those with rapidly increasing total kidney volume and preserved kidney function; it requires monitoring for hepatotoxicity and aquaresis. An angiotensin receptor blocker controls blood pressure and is standard care but does not specifically slow cyst growth. Long-term antibiotics are used for infected cysts, not for slowing progression. Sodium bicarbonate treats metabolic acidosis in CKD but does not slow ADPKD progression. Erythropoietin treats anemia of CKD and has no effect on cyst growth or kidney function decline.', 'Hard', 102, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 45-year-old man presents with his third episode of calcium oxalate nephrolithiasis. He has hypercalciuria on 24-hour urine testing with normal serum calcium. He drinks 1.5 L of fluid per day and eats a high-sodium diet. Which of the following is the most appropriate long-term preventive measure?', '["Allopurinol", "Thiazide diuretic with increased fluid intake and low-sodium diet", "Potassium citrate alone", "High-dose vitamin C supplementation", "Calcium restriction to less than 400 mg per day"]'::jsonb, 1, 'Calcium oxalate stones with idiopathic hypercalciuria are best prevented with a thiazide diuretic, which reduces urinary calcium excretion, combined with increased fluid intake to more than 2.5 L per day and a low-sodium diet, since sodium increases urinary calcium. Allopurinol is used for uric acid stones or hyperuricosuria, not isolated hypercalciuria. Potassium citrate is first-line for hypocitraturia and uric acid stones and helps alkalinize urine, but it is not the primary therapy for hypercalciuria. High-dose vitamin C increases oxalate production and worsens calcium oxalate stone risk. Dietary calcium should not be severely restricted because it increases oxalate absorption and stone risk; normal calcium intake is recommended.', 'Medium', 103, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 60-year-old man with gout presents with flank pain and hematuria. Urinalysis shows acidic urine with pH 5.0. CT shows a radiolucent stone in the renal pelvis. Which of the following is the most appropriate treatment for this type of stone?', '["Thiazide diuretic", "Penicillamine", "Potassium citrate to alkalinize the urine", "Acetohydroxamic acid", "High-dose calcium supplementation"]'::jsonb, 2, 'Uric acid stones are radiolucent on CT, form in acidic urine, and are associated with gout and hyperuricosuria; potassium citrate alkalinizes the urine to a pH of 6.5 to 7.0, which dissolves uric acid stones and prevents recurrence. Thiazide diuretics reduce urinary calcium and are used for calcium oxalate stones with hypercalciuria, not uric acid stones. Penicillamine is a chelating agent used for cystine stones. Acetohydroxamic acid inhibits urease and is used for struvite stones caused by urease-producing organisms. High-dose calcium supplementation does not treat uric acid stones and could increase calcium stone risk.', 'Medium', 104, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 38-year-old woman with recurrent urinary tract infections and a staghorn calculus on imaging has urine pH 8.0 with Proteus mirabilis on culture. Which of the following best describes the composition of her stone?', '["Calcium oxalate", "Uric acid", "Cystine", "Calcium phosphate", "Struvite (magnesium ammonium phosphate)"]'::jsonb, 4, 'Struvite stones are composed of magnesium ammonium phosphate, form in alkaline urine, and are caused by urease-producing organisms such as Proteus mirabilis that split urea into ammonia, raising urine pH; they grow into large staghorn calculi and are strongly associated with recurrent urinary tract infections. Calcium oxalate stones are radiodense and form in normal or slightly acidic urine without a specific organism. Uric acid stones are radiolucent and form in acidic urine. Cystine stones occur in cystinuria, an inherited defect in dibasic amino acid transport, and appear as hexagonal crystals. Calcium phosphate stones form in alkaline urine but are not typically staghorn calculi associated with Proteus infection.', 'Medium', 105, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 28-year-old woman presents with dysuria, urinary frequency, and suprapubic pain for 2 days. She is afebrile with no flank pain or vaginal discharge. Urinalysis shows leukocyte esterase and nitrites. Which of the following is the most appropriate management?', '["Intravenous ceftriaxone and admission", "Nitrofurantoin for 5 days", "A single dose of fosfomycin plus 14 days of ciprofloxacin", "No antibiotics; observation only", "Trimethoprim-sulfamethoxazole for 14 days"]'::jsonb, 1, 'This is uncomplicated cystitis in a healthy nonpregnant woman, which is treated with a short course of nitrofurantoin for 5 days, a first-line agent with low resistance and minimal collateral damage. Intravenous ceftriaxone and admission are reserved for pyelonephritis or complicated infection with fever, flank pain, or sepsis. A single dose of fosfomycin is an alternative but combining it with 14 days of ciprofloxacin is unnecessary and increases resistance and adverse effects. Observation without antibiotics is inappropriate for symptomatic bacterial cystitis. Trimethoprim-sulfamethoxazole is an alternative first-line agent but requires a 3-day course, not 14 days, for uncomplicated cystitis.', 'Easy', 106, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 65-year-old man with diabetes presents with fever, rigors, flank pain, and vomiting for 2 days. Blood pressure is 90/60 mm Hg. Urinalysis shows pyuria and bacteriuria. Blood cultures are drawn. Which of the following is the most appropriate next step in management?', '["Oral nitrofurantoin as an outpatient", "Oral fosfomycin as an outpatient", "Observation and repeat urinalysis in 1 week", "Intravenous ceftriaxone with hospital admission", "Oral phenazopyridine alone"]'::jsonb, 3, 'This patient has acute pyelonephritis with sepsis physiology, suggested by fever, flank pain, vomiting, and hypotension in a diabetic man; complicated upper urinary tract infection requires hospital admission with intravenous antibiotics such as ceftriaxone, with cultures guiding de-escalation. Oral nitrofurantoin does not achieve adequate tissue levels in the kidney and is ineffective for pyelonephritis. Oral fosfomycin is an option for uncomplicated cystitis but is not appropriate for febrile upper tract infection with sepsis. Observation is dangerous in a hypotensive patient with suspected urosepsis. Phenazopyridine only relieves dysuria symptoms and has no antibacterial activity.', 'Medium', 107, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 78-year-old woman in a nursing home has a positive urine culture with 100,000 colony-forming units of Escherichia coli but no dysuria, fever, flank pain, or delirium. Her urinalysis shows pyuria. Which of the following is the most appropriate management?', '["No antibiotics; do not treat asymptomatic bacteriuria", "Oral ciprofloxacin for 7 days", "Intravenous ceftriaxone for 14 days", "Nitrofurantoin for 5 days", "Urinary catheter placement and bladder irrigation"]'::jsonb, 0, 'Asymptomatic bacteriuria should not be treated with antibiotics except in pregnant women and patients undergoing urologic procedures with mucosal bleeding, because treatment does not improve outcomes and increases resistance, Clostridioides difficile infection, and adverse drug effects; pyuria alone does not indicate infection. Oral ciprofloxacin exposes the patient to resistance and tendon toxicity without benefit. Intravenous ceftriaxone is unnecessary and inappropriate for an asymptomatic patient. Nitrofurantoin is not indicated without symptoms and is less effective in older adults with reduced kidney function. Catheter placement and bladder irrigation increase infection risk and are not indicated for asymptomatic bacteriuria.', 'Medium', 108, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 68-year-old man with resistant hypertension on three antihypertensive agents, including a diuretic, is found to have an abdominal bruit and a rise in serum creatinine from 1.1 to 1.8 mg/dL after starting lisinopril. Renal ultrasound shows a small right kidney. Which of the following is the most appropriate next diagnostic test?', '["Duplex ultrasound of the renal arteries", "Renal biopsy", "Intravenous pyelography", "Cystoscopy", "Serum protein electrophoresis"]'::jsonb, 0, 'This patient has renovascular hypertension from renal artery stenosis, suggested by resistant hypertension, an abdominal bruit, asymmetric kidney size, and a rise in creatinine after ACE inhibitor initiation, which reduces perfusion pressure to the stenotic kidney. Duplex ultrasound of the renal arteries is the appropriate noninvasive first test to assess for stenosis and flow velocity. Renal biopsy is not indicated without evidence of glomerular disease and carries bleeding risk. Intravenous pyelography is obsolete and does not assess renal artery flow. Cystoscopy evaluates the bladder and lower urinary tract, not renovascular disease. Serum protein electrophoresis screens for multiple myeloma and is irrelevant to this presentation.', 'Medium', 109, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 55-year-old woman with bilateral renal artery stenosis and resistant hypertension is found to have flash pulmonary edema twice in the past month. Her kidney function is stable. Which of the following is the most appropriate management?', '["Continue medical therapy with an ACE inhibitor alone", "Start high-dose loop diuretics only", "Bilateral nephrectomy", "Renal artery revascularization with stenting", "Sodium bicarbonate infusion"]'::jsonb, 3, 'Revascularization with renal artery stenting is indicated in bilateral renal artery stenosis when the patient has recurrent flash pulmonary edema, which reflects bilateral renovascular disease causing volume overload that cannot be controlled medically; stenting can restore perfusion and reduce recurrent edema. Continuing an ACE inhibitor alone is inadequate for recurrent flash pulmonary edema and risks worsening kidney function in bilateral stenosis. High-dose loop diuretics treat the edema acutely but do not address the underlying bilateral stenosis driving recurrence. Bilateral nephrectomy is not a treatment for renovascular hypertension and would cause end-stage kidney disease. Sodium bicarbonate treats metabolic acidosis, not renovascular hypertension or flash pulmonary edema.', 'Hard', 110, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 45-year-old man receives a deceased-donor kidney transplant. On postoperative day 5, his creatinine rises from 1.4 to 2.6 mg/dL. He has fever and graft tenderness. Doppler ultrasound shows normal perfusion with no obstruction. Biopsy shows interstitial lymphocytic infiltrate with tubulitis. Which of the following is the most likely diagnosis?', '["Acute T-cell mediated rejection", "Antibody-mediated rejection", "Calcineurin inhibitor toxicity", "Recurrent focal segmental glomerulosclerosis", "Cytomegalovirus nephritis"]'::jsonb, 0, 'Acute T-cell mediated rejection typically occurs in the first weeks after transplant with rising creatinine, fever, and graft tenderness; biopsy shows interstitial infiltration by T lymphocytes with tubulitis, and Doppler shows preserved perfusion without obstruction. Antibody-mediated rejection shows peritubular capillaritis, C4d staining, and donor-specific antibodies, often with glomerulitis rather than isolated tubulitis. Calcineurin inhibitor toxicity causes arteriolar hyalinosis and isometric tubular vacuolization without a lymphocytic infiltrate. Recurrent focal segmental glomerulosclerosis presents with heavy proteinuria and glomerular lesions, not tubulitis. Cytomegalovirus nephritis shows viral inclusions and cytomegalic cells on biopsy rather than T-cell tubulitis.', 'Hard', 111, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 60-year-old woman is 3 months post kidney transplant on tacrolimus, mycophenolate, and prednisone. She develops fever, leukopenia, and atypical lymphocytes on blood smear. Her creatinine is rising. Which of the following is the most likely cause?', '["Acute cellular rejection", "Cytomegalovirus infection", "Tacrolimus nephrotoxicity", "Post-transplant lymphoproliferative disorder", "Urinary tract infection"]'::jsonb, 1, 'Cytomegalovirus infection is the most common opportunistic infection in the first months after transplant, presenting with fever, leukopenia, atypical lymphocytosis, hepatitis, and rising creatinine from CMV nephritis or systemic disease, especially in a CMV-seronegative recipient of a seropositive donor. Acute cellular rejection causes rising creatinine and graft tenderness but not fever with leukopenia and atypical lymphocytes. Tacrolimus nephrotoxicity causes rising creatinine with tremor and hyperkalemia but not fever or atypical lymphocytosis. Post-transplant lymphoproliferative disorder is driven by Epstein-Barr virus and typically presents later with lymphadenopathy or a mass. Urinary tract infection causes dysuria and pyuria without leukopenia or atypical lymphocytes.', 'Medium', 112, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 50-year-old man is 2 years post kidney transplant on tacrolimus and mycophenolate. His creatinine has slowly risen over 6 months. Biopsy shows interstitial fibrosis, tubular atrophy, and arteriolar hyalinosis without significant inflammation. Which of the following is the most likely cause of his chronic graft dysfunction?', '["Acute antibody-mediated rejection", "Recurrent IgA nephropathy", "Polyoma BK virus nephropathy", "Chronic calcineurin inhibitor toxicity", "Renal artery stenosis"]'::jsonb, 3, 'Chronic calcineurin inhibitor toxicity from long-term tacrolimus causes progressive interstitial fibrosis, tubular atrophy, and arteriolar hyalinosis with a slow rise in creatinine and little inflammation on biopsy. Acute antibody-mediated rejection presents with a rapid creatinine rise, peritubular capillaritis, C4d deposition, and donor-specific antibodies. Recurrent IgA nephropathy shows mesangial IgA deposits with hematuria and proteinuria. Polyoma BK virus nephropathy shows viral inclusions in tubular cells with interstitial inflammation and is associated with high BK viral load. Renal artery stenosis causes hypertension and a rise in creatinine often after ACE inhibitor use, with Doppler evidence of stenosis.', 'Hard', 113, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 30-year-old man presents with painless gross hematuria after an upper respiratory infection. Urinalysis shows dysmorphic red blood cells and red blood cell casts. Serum creatinine is normal and there is no proteinuria. Which of the following is the most likely source of the hematuria?', '["Ureteral stone", "Glomerular", "Bladder tumor", "Benign prostatic hyperplasia", "Urinary tract infection"]'::jsonb, 1, 'Dysmorphic red blood cells and red blood cell casts indicate a glomerular source of hematuria, as the red cells are distorted while passing through the glomerular basement membrane and casts form in the tubules; painless hematuria following an upper respiratory infection is classic for IgA nephropathy. A ureteral stone causes colicky flank pain with hematuria but without dysmorphic cells or casts. A bladder tumor causes painless gross hematuria in older patients, usually with normal red cell morphology and no casts. Benign prostatic hyperplasia causes hematuria with obstructive voiding symptoms in older men, not dysmorphic cells. Urinary tract infection causes dysuria, pyuria, and bacteriuria rather than dysmorphic red cells and casts.', 'Medium', 114, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 65-year-old man who smoked for 40 years presents with painless gross hematuria. Urinalysis shows normal-appearing red blood cells without casts or dysmorphic cells, and no proteinuria. He has no dysuria or flank pain. Which of the following is the most appropriate next step in evaluation?', '["Cystoscopy and CT urography", "Renal biopsy", "Repeat urinalysis in 6 months", "Serum protein electrophoresis", "Prostate-specific antigen testing alone"]'::jsonb, 0, 'Painless gross hematuria with normal-appearing red blood cells and no casts indicates a nonglomerular, lower urinary tract source, and in an older smoker the priority is to exclude bladder cancer and upper tract urothelial malignancy with cystoscopy and CT urography. Renal biopsy is indicated for glomerular hematuria with dysmorphic cells, casts, or proteinuria, which are absent here. Repeating urinalysis in 6 months would delay diagnosis of a potentially curable malignancy. Serum protein electrophoresis screens for myeloma and does not evaluate hematuria. Prostate-specific antigen testing alone is insufficient and does not evaluate the bladder or upper urinary tract in a smoker with gross hematuria.', 'Medium', 115, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 16-year-old boy is found to have proteinuria of 800 mg per day on a routine urine test, but a first-morning urine sample shows only 80 mg per day with normal kidney function and no hematuria. Which of the following is the most likely diagnosis?', '["Nephrotic syndrome", "Diabetic nephropathy", "Membranous nephropathy", "Focal segmental glomerulosclerosis", "Orthostatic proteinuria"]'::jsonb, 4, 'Orthostatic proteinuria is a benign condition in adolescents in which protein excretion is elevated while upright during the day but normal in a first-morning supine sample, with normal kidney function and no hematuria; it requires no treatment and carries an excellent prognosis. Nephrotic syndrome causes heavy proteinuria above 3.5 g per day with hypoalbuminemia, edema, and hyperlipidemia. Diabetic nephropathy causes persistent albuminuria with diabetes and progressive kidney disease. Membranous nephropathy causes persistent nephrotic-range proteinuria in adults. Focal segmental glomerulosclerosis causes persistent proteinuria with progressive kidney dysfunction, not proteinuria that disappears in the morning sample.', 'Easy', 116, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 55-year-old woman with type 2 diabetes has a urine albumin-to-creatinine ratio of 450 mg/g on two separate occasions, with an estimated glomerular filtration rate of 58 mL/min/1.73 m2. Her blood pressure is 128/78 mm Hg on lisinopril. Which of the following is the most appropriate next step in management?', '["Stop the ACE inhibitor", "Start high-dose loop diuretics", "Perform a renal biopsy", "Restrict protein intake to less than 0.3 g/kg/day", "Add an SGLT2 inhibitor"]'::jsonb, 4, 'This patient has diabetic kidney disease with moderately increased albuminuria and reduced kidney function; SGLT2 inhibitors reduce progression of kidney disease and cardiovascular events in diabetic kidney disease even when blood pressure and glucose are controlled, and are recommended in addition to ACE inhibitor therapy. Stopping the ACE inhibitor would remove its antiproteinuric and kidney-protective benefit. High-dose loop diuretics are used for volume overload, not for slowing diabetic kidney disease progression. Renal biopsy is not routinely needed for classic diabetic kidney disease with albuminuria and reduced kidney function. Severe protein restriction below 0.3 g/kg per day risks malnutrition and is not recommended; moderate protein intake of about 0.8 g/kg per day is advised.', 'Medium', 117, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 40-year-old man with chronic kidney disease has serum bicarbonate 17 mEq/L, potassium 5.4 mEq/L, and calcium 8.0 mg/dL with phosphate 5.2 mg/dL. He reports muscle cramps and perioral tingling. Which of the following is the most appropriate initial management of his metabolic acidosis?', '["Intravenous calcium gluconate followed by bicarbonate therapy", "High-dose loop diuretics", "Oral sodium bicarbonate", "Sodium polystyrene sulfonate alone", "Immediate hemodialysis"]'::jsonb, 2, 'Chronic metabolic acidosis in CKD is treated with oral sodium bicarbonate to maintain serum bicarbonate above 22 mEq/L, which slows kidney disease progression and improves bone health; his mild hyperkalemia and hyperphosphatemia also improve with acidosis correction. Intravenous calcium gluconate is for symptomatic hypocalcemia with cardiac instability, and his symptoms are more consistent with chronic acidosis and CKD mineral bone disease than acute severe hypocalcemia. High-dose loop diuretics worsen volume depletion and kidney function. Sodium polystyrene sulfonate treats hyperkalemia but not the underlying acidosis. Immediate hemodialysis is reserved for severe refractory acidosis, uremic complications, or volume overload unresponsive to medical therapy.', 'Medium', 118, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 24-year-old woman with systemic lupus erythematosus presents with polyuria and polydipsia. Labs show sodium 152 mEq/L, potassium 3.1 mEq/L, and a normal anion gap metabolic acidosis with urine pH 6.8. She has no history of lithium use. Which of the following is the most likely cause of her tubular dysfunction?', '["Proximal renal tubular acidosis from Fanconi syndrome", "Type 4 renal tubular acidosis from hypoaldosteronism", "Distal renal tubular acidosis from interstitial nephritis", "Bartter syndrome", "Diabetes insipidus from pituitary involvement"]'::jsonb, 2, 'Systemic lupus erythematosus can cause tubulointerstitial nephritis with distal tubular dysfunction, producing type 1 (distal) RTA with a normal anion gap metabolic acidosis, hypokalemia, and an inappropriately alkaline urine pH above 5.5; autoimmune diseases such as Sjogren syndrome and lupus are classic causes of acquired distal RTA. Proximal RTA with Fanconi syndrome would show glycosuria, phosphaturia, and aminoaciduria with urine pH below 5.5. Type 4 RTA causes hyperkalemia, not hypokalemia. Bartter syndrome causes metabolic alkalosis, not acidosis. Central diabetes insipidus from pituitary involvement would cause hypernatremia with dilute urine but not a normal anion gap metabolic acidosis.', 'Hard', 119, 'MCQ'),
('ee8aa5ac-be78-465b-9552-d70db2b848a7', 'A 70-year-old man with heart failure on furosemide presents with confusion and sodium 118 mEq/L. He has edema, serum osmolality 250 mOsm/kg, urine osmolality 400 mOsm/kg, and urine sodium 45 mEq/L. Which of the following best explains his hyponatremia?', '["SIADH from occult malignancy", "Hypovolemic hyponatremia from diuretic use", "Primary polydipsia", "Adrenal insufficiency", "Hypervolemic hyponatremia from heart failure with nonosmotic ADH release"]'::jsonb, 4, 'In heart failure, reduced effective arterial blood volume triggers nonosmotic ADH release, causing water retention that exceeds sodium retention and producing hypervolemic hyponatremia with edema, concentrated urine, and elevated urine sodium; the clinical picture of edema and heart failure distinguishes it from SIADH. SIADH causes euvolemic hyponatremia without edema or signs of heart failure. Hypovolemic hyponatremia from diuretics presents with dry mucous membranes, orthostasis, and low urine sodium from volume depletion. Primary polydipsia causes very dilute urine with low urine osmolality, not concentrated urine. Adrenal insufficiency causes hyponatremia with hyperkalemia, hypotension, and often hypoglycemia, which are absent here.', 'Medium', 120, 'MCQ');
